let projects=[], activeId, active, continuity, view='overview', activeEpisodeId=null, activeSceneId=null, activeShotId=null;
let workspaceMode=localStorage.getItem('ai-video-studio:workspace-mode')||'guided';
let sidebarCollapsed=localStorage.getItem('ai-video-studio:sidebar-collapsed')===null ? window.matchMedia('(max-width:620px)').matches : localStorage.getItem('ai-video-studio:sidebar-collapsed')==='true';
let scriptFontSize=Math.min(18,Math.max(13,Number(localStorage.getItem('ai-video-studio:script-font-size'))||15));
let assistantInfo={configured:false,engine:'local-planner'}, assistantDraft=null, assistantBusy=false, assistantError='', assistantInstruction='', returnToAssistantFocus=false;
let annotationTool='arrow', annotationColor='#ffcc66', annotationItems=[], annotationDraft=null, annotationRedraw=null, voiceNotices={}, imageBriefText='', autopilotBusy=false, autopilotError='', editorState=null, editorNotice='', editorError='';
const labels={type:{general:'Універсальне відео',science:'Наукове відео','animated-series':'Анімаційний серіал'},status:{idea:'ідея',development:'розробка',draft:'чернетка','in-review':'на перевірці','in-progress':'у роботі',approved:'затверджено',production:'виробництво',released:'випущено',superseded:'замінено',planned:'заплановано',original:'оригінал',archived:'в архіві',hidden:'приховано'},age:{child:'дитина',teen:'підліток','young-adult':'молодий дорослий',adult:'дорослий',elder:'літня людина'},language:{uk:'Українська',en:'Англійська'},asset:{'blender-rig':'Blender-ріг','blender-scene':'Blender-сцена',reference:'Референс',image:'Зображення',video:'Відео',audio:'Аудіо',music:'Музика',ambient:'Атмосфера',sfx:'SFX',export:'Експорт'},scope:{character:'персонаж',location:'локація',object:'об’єкт',style:'стиль',scene:'сцена',shot:'шот',audio:'аудіо',other:'інше'},workflow:{strategy:'Стратегія',script:'Сценарій',assets:'Ресурси',storyboard:'Розкадрування',voice:'Звук і голоси',animation:'Анімація / рендер',assembly:'Збірка',export:'Експорт'},workflowStatus:{'not-started':'не розпочато','in-progress':'у роботі',ready:'готово',blocked:'заблоковано'}};
const $=s=>document.querySelector(s);const esc=s=>String(s||'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const label=(group,value)=>labels[group]?.[value]||value;
function voiceSlider(name,title,left,right,value,help,min=0,max=1,step=.05){return `<label class="voice-setting"><span><b>${title}</b><output class="voice-setting-value">${esc(value)}</output></span><small class="voice-scale"><i>${left}</i><i>${right}</i></small><input name="${name}" type="range" min="${min}" max="${max}" step="${step}" value="${esc(value)}" oninput="this.closest('.voice-setting').querySelector('.voice-setting-value').textContent=this.value"><small>${help}</small></label>`}
async function api(path,options={}){const r=await fetch(path,{headers:{'content-type':'application/json'},...options});const d=await r.json();if(!r.ok)throw Error(d.error||'Помилка');return d}
async function load(id){projects=await api('/api/projects');const savedId=localStorage.getItem('ai-video-studio:last-project-id');const preferredId=id||activeId||savedId;activeId=projects.some(project=>project.id===preferredId)?preferredId:projects[0]?.id;if(activeId)localStorage.setItem('ai-video-studio:last-project-id',activeId);active=await api(`/api/projects/${encodeURIComponent(activeId)}`);continuity=await api(`/api/projects/${encodeURIComponent(activeId)}/continuity`).catch(()=>null);assistantInfo=await api(`/api/projects/${encodeURIComponent(activeId)}/assistant/status`).catch(()=>({configured:false,engine:'local-planner'}));render()}
function render(){const b=active.bibles;$('#projects').innerHTML=projects.map(p=>`<button class="project ${p.id===activeId?'active':''}" data-project-id="${esc(p.id)}">${esc(p.name)}<small>${esc(label('type',p.type))} · ${p.targetMinutes} хв</small></button>`).join('');document.querySelectorAll('[data-project-id]').forEach(button=>button.addEventListener('click',()=>selectProject(button.dataset.projectId)));renderGlobalNav();renderWorkspaceNav();const globalZone=['home','projects','models','modelSetup','queue','assistants','settings'].includes(view);const zoneTitle=$('#aps-zone-title');if(zoneTitle)zoneTitle.textContent=globalZone?viewTitle():(view==='overview'?active.name:viewTitle());$('#content').innerHTML=`<div class="hero ${view==='overview'?'dashboard-hero':''}"><div><p class="eyebrow">${globalZone?'ГЛОБАЛЬНА ЗОНА · НЕ ПРИВ’ЯЗАНА ДО ПРОЄКТУ':`${esc(label('type',active.type))} · ${esc(label('language',active.defaultLanguage))} · ЧЕРНЕТКОВА РОБОТА`}</p><h2>${esc(viewTitle())}</h2><p>${esc(globalZone?'Керуйте моделями, чергою та межами помічників окремо від матеріалів проєкту.':view==='overview'?'Поточний випуск, його готовність і лише одна наступна дія.':'Проєкт: '+active.name)}</p></div><div class="hero-tools">${view==='overview'||globalZone?'':`<div class="workspace-mode" role="group" aria-label="Режим роботи"><button class="${workspaceMode==='guided'?'active':''}" onclick="setWorkspaceMode('guided')">Мій маршрут</button><button class="${workspaceMode==='studio'?'active':''}" onclick="setWorkspaceMode('studio')">Робочий стіл</button></div>`}<div class="actions">${viewActions()}</div></div></div><div class="grid">${pageContent()}</div>`;renderDialogueQuickAccess()}
function renderGlobalNav(){const nav=$('#global-nav');if(!nav)return;const items=[['overview','⌂','Проєкт'],['models','◈','Моделі'],['queue','≡','Черга'],['assistants','✦','Помічники']];nav.innerHTML=items.map(([id,icon,name])=>`<button class="global-nav-item ${view===id?'active':''}" type="button" data-global-view="${id}" ${view===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${name}</button>`).join('');nav.querySelectorAll('[data-global-view]').forEach(button=>button.addEventListener('click',async()=>{view=button.dataset.globalView;workspaceMode=view==='overview'?'guided':'studio';localStorage.setItem('ai-video-studio:workspace-mode',workspaceMode);if(typeof refreshProductionStudio==='function')await refreshProductionStudio();render()}))}
function renderDialogueQuickAccess(){if(view!=='episodes'||!activeEpisodeId)return;const episode=active.episodes.find(item=>item.id===activeEpisodeId);if(!episode)return;const scenes=active.scenes.filter(scene=>scene.episodeId===episode.id).sort((a,b)=>Number(a.order||0)-Number(b.order||0));const lines=scenes.flatMap(scene=>(scene.dialogue||[]).map(line=>({scene,line})));const shots=scenes.flatMap(scene=>(scene.shots||[]).map((shot,index)=>({scene,shot,index})));const shotPanel=document.createElement('article');shotPanel.className='card full';shotPanel.id='episode-shots';shotPanel.innerHTML=`<h3>Шоти випуску</h3>${shots.length?shots.map(({scene,shot,index})=>`<div class="item"><strong>${esc(scene.title)} · Шот ${index+1} <span class="tag">${esc(shot.seconds)} с</span></strong><span class="muted">${esc(shot.camera)} · ${esc(shot.imagePrompt||shot.prompt||'Опис кадру не задано')}</span><button onclick="viewSceneShots('${scene.id}')">Переглянути у розкадруванні</button></div>`).join(''):'<p class="empty">У сценах цього випуску ще немає шотів.</p>'}`;const dialoguePanel=document.createElement('article');dialoguePanel.className='card full';dialoguePanel.id='episode-dialogue';dialoguePanel.innerHTML=`<h3>Репліки випуску</h3>${lines.length?lines.map(({scene,line})=>`<div class="item"><strong>${esc(scene.title)} · ${esc(active.bibles.characters.find(character=>character.id===line.characterId)?.name||'Персонаж')}</strong><span class="muted">UA: ${esc(line.textUk||(line.language==='uk'?line.text:'—'))}</span><span class="muted">EN: ${esc(line.textEn||(line.language==='en'?line.text:'—'))}</span><span class="muted">Емоція: ${esc(line.emotion||'не задано')} · ${esc(label('status',line.status||'draft'))}</span><button onclick="openDialogue('${scene.id}','${line.id}')">Відкрити й редагувати</button></div>`).join(''):'<p class="empty">У сценах цього випуску ще немає реплік.</p>'}`;$('#episode-editor')?.after(dialoguePanel);$('#episode-editor')?.after(shotPanel)}
function renderWorkspaceNav(){const main=[['script','✏','1. Сценарій','Історія, сцени, репліки'],['audio','🔊','2. Аудіо','Голоси, темп, мовні версії'],['storyboard','▣','3. Відеоряд','Кадри, зображення, рух'],['preview','✓','4. Збірка','Перевірка готовності до монтажу']],advanced=[['episodes','☷','Випуски'],['assets','▤','Персонажі та світ'],['versions','↶','Історія версій'],['production','⚙','Технічні інструменти']],navButton=(id,icon,name,hint='')=>`<button class="project nav-project ${view===id?'active':''}" data-view="${id}" title="${esc(name)}"><span class="nav-icon" aria-hidden="true">${icon}</span><span class="nav-copy"><strong>${name}</strong>${hint?`<small>${hint}</small>`:''}</span></button>`;let nav=$('#workspace-nav');if(!nav){nav=document.createElement('nav');nav.id='workspace-nav';$('#projects').after(nav)}nav.innerHTML=`<p class="nav-label">ПОЧНІТЬ ЗВІДСИ</p>${navButton('overview','⌂','Робочий стіл','Одна наступна дія')}<p class="nav-label nav-label-route">ВИРОБНИЦТВО ВИПУСКУ</p><div class="nav-route">${main.map(([id,icon,name,hint])=>navButton(id,icon,name,hint)).join('')}</div><p class="nav-label">БІБЛІОТЕКА Й ІНСТРУМЕНТИ</p><div class="nav-extra">${advanced.map(([id,icon,name])=>navButton(id,icon,name)).join('')}</div><p class="side-note">Кожне збереження лишає попередню версію. Відкрити її можна в «Історії версій».</p>`;nav.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{view=button.dataset.view;workspaceMode=view==='overview'?'guided':'studio';localStorage.setItem('ai-video-studio:workspace-mode',workspaceMode);render()}))}
function setWorkspaceMode(mode){workspaceMode=mode;localStorage.setItem('ai-video-studio:workspace-mode',mode);if(mode==='guided')view='overview';else if(view==='overview')view=activeEpisodeId?'episodes':'storyboard';render()}
function viewTitle(){return ({overview:'Робочий стіл',autopilot:'Новий випуск',episodes:'Випуски та сезон',script:'1. Сценарій',editor:'Редактор сценарію',storyboard:'3. Відеоряд',assets:'Персонажі та світ',audio:'2. Аудіо',preview:'4. Збірка',versions:'Історія версій',production:'Технічні інструменти'})[view]}
function viewActions(){if(view==='overview')return '<button class="primary" onclick="goToView(\'autopilot\')">Створити випуск</button><button onclick="goToView(\'script\')">Відкрити сценарій</button>';if(view==='autopilot')return '<button onclick="goToView(\'overview\')">До робочого столу</button>';if(view==='episodes')return `<button onclick="openEpisode()">＋ Випуск</button>${activeEpisodeId?`<button onclick="downloadEpisodePackage('${activeEpisodeId}')">Завантажити пакет</button>`:''}`;if(view==='script')return '<button onclick="openScript()">＋ Сценарій</button>';if(view==='storyboard')return '<button onclick="openScene()">＋ Нова сцена</button>';if(view==='assets')return '<button class="primary" onclick="openImageUpload()">↑ Завантажити зображення</button><button onclick="openAsset()">＋ Ресурс</button>';if(view==='audio')return '<button onclick="openVoiceProfile()">＋ Голос</button><button onclick="goToView(\'sound\')">Звук і музика</button><button onclick="openLocalization()">＋ Мовна версія</button>';if(view==='preview')return '<button onclick="goToView(\'storyboard\')">Відкрити кадри</button><button onclick="goToView(\'audio\')">Відкрити аудіо</button>';if(view==='versions')return '';if(view==='production')return '<button onclick="validate()">Перевірити готовність</button>';return ''}
function pageContent(){if(view==='autopilot')return autopilotPanel();if(view==='episodes')return episodePanel();if(view==='script')return `${assistantPanel()}${scriptPanel()}${profileCard()}`;if(view==='storyboard')return storyboardWorkspace();if(view==='assets')return `<article class="card"><h3>Біблія стилю <button class="scene-actions" onclick="openBible('style')">＋</button></h3>${listBible(active.bibles.style,'style')}</article><article class="card"><h3>Біблія персонажів <button class="scene-actions" onclick="openBible('characters')">＋</button></h3>${listBible(active.bibles.characters,'characters')}</article>${assetPanel()}${continuityPanel()}`;if(view==='audio')return `${voicePanel()}${localizationPanel()}`;if(view==='preview')return previewPanel();if(view==='versions')return versionPanel();if(view==='production')return `${productionReviewPanel()}${productionPanel()}${renderQueuePanel()}${continuityPanel()}`;return overviewNextSteps()}
function episodeProgress(episode){const scenes=active.scenes.filter(scene=>scene.episodeId===episode?.id),shots=scenes.flatMap(scene=>scene.shots||[]),lines=scenes.flatMap(scene=>scene.dialogue||[]),assetsById=new Map((active.assets||[]).map(asset=>[asset.id,asset]));const storyReady=(active.scripts||[]).some(script=>(script.episodeId===episode?.id||!script.episodeId)&&script.status==='approved');const shotsReady=shots.length>0&&scenes.every(scene=>['approved','production'].includes(scene.status))&&shots.every(shot=>{const key=assetsById.get(shot.keyImageAssetId);return shot.status==='approved'&&key&&['image','reference'].includes(key.type)&&key.status==='approved'});const voicesReady=lines.length>0&&lines.every(line=>line.status==='approved'&&(line.audioDrafts||[]).some(audio=>audio.language===line.language&&audio.status==='approved'));const reviewReady=storyReady&&shotsReady&&voicesReady&&['approved','production','released'].includes(episode?.status);return {scenes,shots,lines,storyReady,scenesReady:scenes.length>0,shotsReady,voicesReady,reviewReady}}
function overviewNextSteps(){
 const episode=(active.episodes||[]).find(item=>item.id===activeEpisodeId)||(active.episodes||[])[0];
 if(!window.APSProjectDashboard?.render)throw new Error('Project dashboard renderer not loaded');
 return window.APSProjectDashboard.render({
  name:active.name,
  episodes:active.episodes||[],
  assets:active.assets||[],
  characters:active.bibles?.characters||[],
  progress:episodeProgress(episode),
  statusLabel:status=>label('status',status)
 });
}
function autopilotPanel(){const characters=(active.bibles?.characters||[]).filter(item=>item.status==='approved');const styles=(active.bibles?.style||[]).filter(item=>item.status==='approved');return `<article class="card full autopilot-card"><div class="autopilot-head"><div><p class="eyebrow">АВТОПІЛОТ ЕПІЗОДУ · ЧЕРНЕТКА</p><h3>Одна команда → редагований план випуску</h3><p class="muted">Опишіть задум своїми словами або вставте текст із голосової нотатки. Студія створить сценарну чернетку, сцени та шоти — усе можна одразу редагувати.</p></div><span class="tag">без платної генерації</span></div><div class="conveyor"><span class="active">1. Ідея</span><span>2. Сценарій</span><span>3. Кадри</span><span>4. Рух</span><span>5. Голос</span><span>6. Збірка</span></div><label class="autopilot-brief"><strong>Що має відбутися у випуску?</strong><textarea id="autopilot-brief" placeholder="Наприклад: Лума знаходить згаслий ліхтарик друга, спочатку уважно вислуховує його, а потім вони разом повертають світло."></textarea><small>Автопілот не затверджує сюжет і не створює фінальні матеріали самостійно.</small></label><div class="autopilot-options"><label>Назва (необов’язково)<input id="autopilot-title" placeholder="Новий короткий випуск"></label><label>Тривалість, хв<input id="autopilot-minutes" type="number" min="0.5" max="20" step="0.5" value="1"></label><label>Формат кадру<select id="autopilot-format"><option>16:9</option><option>9:16</option><option>1:1</option></select></label><label>План руху<select id="autopilot-motion"><option value="animatic">Лише аніматик для перевірки</option><option value="selected-shots">Позначити кандидати на оживлення</option></select></label></div><div class="autopilot-context"><span>Персонажі: <strong>${characters.length?characters.map(item=>esc(item.name)).join(', '):'ще не затверджено'}</strong></span><span>Стиль: <strong>${styles.length?`${styles.length} правило(а)`:'ще не затверджено'}</strong></span><span>Збереження: <strong>автоматично у версіях</strong></span></div><div class="actions"><button class="primary" onclick="createAutopilotEpisode()" ${autopilotBusy?'disabled':''}>${autopilotBusy?'Створюємо план…':'Створити чернетку випуску'}</button><button onclick="goToView('script')">Працювати вручну</button></div>${autopilotError?`<p class="assistant-error">${esc(autopilotError)}</p>`:''}<p class="autopilot-note">Зараз працює локальний планувальник: він використовує вашу біблію персонажів, правила стилю та задум. Nano Banana Pro, Veo/Runway і ElevenLabs підключатимуться окремо — лише до вибраних вами кадрів і реплік.</p></article>`}
async function createAutopilotEpisode(){const input={brief:$('#autopilot-brief')?.value||'',title:$('#autopilot-title')?.value||'',targetMinutes:$('#autopilot-minutes')?.value||1,format:$('#autopilot-format')?.value||'16:9',motionMode:$('#autopilot-motion')?.value||'animatic'};autopilotBusy=true;autopilotError='';render();try{const result=await api(`/api/projects/${encodeURIComponent(activeId)}/autopilot/episode`,{method:'POST',body:JSON.stringify(input)});activeEpisodeId=result.episode.id;view='episodes';workspaceMode='studio';localStorage.setItem('ai-video-studio:workspace-mode',workspaceMode);await load(activeId)}catch(error){autopilotError=error.message==='not found'?'Автопілот додано, але локальний сервер ще працює у попередній версії. Зупиніть його та запустіть npm start ще раз, потім оновіть сторінку.':error.message;autopilotBusy=false;render()} }
function goToView(nextView){view=nextView;workspaceMode=nextView==='overview'?'guided':'studio';localStorage.setItem('ai-video-studio:workspace-mode',workspaceMode);render()}
function assistantMaterialsPanel(episode){const scripts=(active.scripts||[]).filter(script=>!episode||!script.episodeId||script.episodeId===episode.id),visuals=active.assets.filter(asset=>asset.type==='reference'&&typeof asset.uri==='string'&&asset.uri.startsWith('/'));return `<details class="assistant-materials"><summary>Матеріали, які бачить помічник: ${scripts.length} сценарій(їв) · ${active.assets.length} ресурсів · ${visuals.length} візуальних референсів</summary><p class="materials-hint">Для комфортного читання, редагування та перегляду зображень натисніть «Відкрити режим фокусу».</p><div class="assistant-material-grid compact"><section><span>Наявний сценарій</span>${scripts.length?scripts.map(script=>`<article><strong>${esc(script.title)}</strong><small>${esc(label('status',script.status))}</small><button onclick="openScript('${script.id}')">Редагувати текст</button></article>`).join(''):'<p>Поки немає окремого сценарного документа.</p>'}</section><section class="assistant-visuals"><span>Візуальні референси</span>${visuals.length?visuals.map(asset=>`<button class="assistant-reference" onclick="showReference('${esc(asset.id)}')"><img src="${esc(asset.uri)}" alt="${esc(asset.label)}"><strong>${esc(asset.label)}</strong></button>`).join(''):'<p>Локальних зображень ще немає.</p>'}</section></div></details>`}
function assistantPanel(){const episode=(active.episodes||[]).find(item=>item.id===activeEpisodeId)||(active.episodes||[])[0];const draft=assistantDraft?.draft;return `<article class="card full assistant-card"><div class="assistant-head"><div><p class="eyebrow">ПОМІЧНИК СЦЕНАРИСТА</p><h3>Чернетка з контекстом усього проєкту</h3><p class="muted">Помічник бачить сценарій, сцени, репліки, персонажів, стиль і референси. Він нічого не затверджує та не зберігає без вашої дії.</p></div><div class="actions"><span class="tag">${assistantInfo.configured?'модель підключено':'локальний режим'}</span><button onclick="openAssistantFocus()">⛶ Відкрити режим фокусу</button></div></div><div class="assistant-context"><span>Випуск: <strong>${esc(episode?.title||'ще не вибрано')}</strong></span><span>Персонажі: <strong>${active.bibles.characters.length}</strong></span><span>Сцени: <strong>${active.scenes.filter(scene=>!episode||scene.episodeId===episode.id).length}</strong></span><span>Стиль: <strong>${active.bibles.style.length} правил</strong></span></div>${assistantMaterialsPanel(episode)}<label class="assistant-instruction"><strong>Напишіть помічнику, що саме треба змінити або створити</strong><textarea id="assistant-instruction" placeholder="Наприклад: перепиши початок спокійніше; у Луми має бути більше сумніву; додай коротку репліку перед сценою 2.">${esc(assistantInstruction)}</textarea><small>Це лише завдання для чернетки. Ви зможете відредагувати текст перед збереженням.</small></label><div class="actions"><button class="primary" onclick="requestAssistantDraft()" ${assistantBusy?'disabled':''}>${assistantBusy?'Готуємо чернетку…':'Створити чернетку сценарію'}</button><button onclick="clearAssistantDraft()" ${draft?'':'disabled'}>Очистити результат</button></div>${assistantError?`<p class="assistant-error">${esc(assistantError)}</p>`:''}${draft?`<div class="assistant-result"><div><p class="eyebrow">РЕЗУЛЬТАТ · ${assistantDraft.engine==='connected-model'?'ПІДКЛЮЧЕНА МОДЕЛЬ':'ЛОКАЛЬНИЙ ПЛАНУВАЛЬНИК'}</p><h4>${esc(draft.title)}</h4><p class="muted">${esc(draft.logline)}</p></div><pre>${esc(draft.body)}</pre><p class="muted">${esc(draft.note)}</p><div class="actions"><button class="primary" onclick="openAssistantScriptDraft()">Відкрити й відредагувати як нову чернетку</button></div></div>`:`<p class="assistant-note">${assistantInfo.configured?'Модель використає цей контекст для пропозиції. Перед збереженням ви зможете відредагувати кожен рядок.':'Локальний планувальник уже використовує повний набір матеріалів і вміє створити чернетку передісторії. Після підключення моделі ця сама панель зможе розгорнути її у повний творчий текст.'}</p>`}</article>`}
async function requestAssistantDraft(){assistantInstruction=$('#assistant-instruction')?.value||assistantInstruction;assistantBusy=true;assistantError='';render();try{assistantDraft=await api(`/api/projects/${encodeURIComponent(activeId)}/assistant/draft`,{method:'POST',body:JSON.stringify({task:'script',episodeId:activeEpisodeId||active.episodes?.[0]?.id||'',instruction:assistantInstruction})})}catch(error){assistantError=error.message==='not found'?'Помічник оновлено, але локальний сервер ще працює у попередній версії. Зупиніть його та запустіть npm start ще раз, після чого оновіть сторінку.':error.message}finally{assistantBusy=false;render()}}
function clearAssistantDraft(){assistantDraft=null;assistantError='';assistantInstruction='';render()}
function openAssistantScriptDraft(){if(assistantDraft?.draft)openScript('',assistantDraft.draft)}
function openAssistantFocus(){returnToAssistantFocus=false;$('#modal-cancel').textContent='Скасувати';const episode=(active.episodes||[]).find(item=>item.id===activeEpisodeId)||(active.episodes||[])[0],scripts=(active.scripts||[]).filter(script=>!episode||!script.episodeId||script.episodeId===episode.id),visuals=active.assets.filter(asset=>asset.type==='reference'&&typeof asset.uri==='string'&&asset.uri.startsWith('/'));$('#modal').classList.add('focus-dialog');$('#modal-title').textContent='Режим фокусу: сценарій і референси';$('#modal-fields').innerHTML=`<div class="focus-workspace"><section class="focus-script"><p class="eyebrow">СЦЕНАРІЙ</p>${scripts.length?scripts.map(script=>`<article><div><strong>${esc(script.title)}</strong><small>${esc(label('status',script.status))}</small></div><p>${esc(script.body||'Текст ще не додано.')}</p><button onclick="openScriptFromFocus('${script.id}')">Редагувати сценарій</button></article>`).join(''):'<p class="empty">Сценарію ще немає. Створіть його у кроці «1. Сценарій».</p>'}</section><section class="focus-visuals"><p class="eyebrow">ВІЗУАЛЬНІ РЕФЕРЕНСИ</p>${visuals.length?visuals.map(asset=>`<button class="focus-reference" onclick="showReferenceFromFocus('${asset.id}')"><img src="${esc(asset.uri)}" alt="${esc(asset.label)}"><strong>${esc(asset.label)}</strong><small>${asset.notes?esc(asset.notes):'Натисніть, щоб збільшити або додати нотатку.'}</small></button>`).join(''):'<p class="empty">Візуальних референсів ще немає.</p>'}</section><section class="focus-request"><label><strong>Що треба змінити?</strong><textarea id="focus-assistant-instruction" placeholder="Опишіть правку простою мовою: що прибрати, що додати, який настрій або репліку змінити…">${esc(assistantInstruction)}</textarea><small>Повідомлення буде перенесено у поле помічника, але нічого не змінить автоматично.</small></label></section></div>`;const form=$('#modal-form'),submit=form.querySelector('button[type="submit"]');submit.textContent='Передати помічнику';form.onsubmit=e=>{e.preventDefault();assistantInstruction=$('#focus-assistant-instruction')?.value||'';closeModal();render()};$('#modal').showModal()}
function openScriptFromFocus(scriptId){returnToAssistantFocus=true;$('#modal').close();$('#modal').classList.remove('focus-dialog');openScript(scriptId)}
function showReferenceFromFocus(assetId){returnToAssistantFocus=true;$('#modal').close();$('#modal').classList.remove('focus-dialog','reference-dialog');showReference(assetId)}
function assetPreview(asset){const isImage=typeof asset.uri==='string'&&/\.(png|jpe?g|webp)$/i.test(asset.uri);return typeof asset.uri==='string'&&asset.uri.startsWith('/')?`<div class="asset-preview">${isImage?`<button class="visual-reference" onclick="showReference('${esc(asset.id)}')"><img src="${esc(asset.uri)}" alt="${esc(asset.label)}"><span>Натисніть, щоб збільшити</span></button>`:''}<div class="actions">${isImage?`<button onclick="showReference('${esc(asset.id)}')">Збільшити</button>`:''}<a class="asset-link" href="${esc(asset.uri)}" target="_blank" rel="noopener">Відкрити файл</a></div></div>`:''}
function assetPanel(){return `<article class="card full"><h3>Бібліотека ресурсів <button class="scene-actions" onclick="openAsset()">＋</button></h3>${active.assets.length?active.assets.map(a=>`<div class="item"><strong>${esc(a.label)}</strong><span class="tag">${esc(label('asset',a.type))}</span> <span class="muted">${esc(label('scope',a.scope||'other'))} · ${esc(a.version)} · ${esc(label('status',a.status))}${a.linkedCharacterId?` · персонаж: ${esc(active.bibles.characters.find(c=>c.id===a.linkedCharacterId)?.name||a.linkedCharacterId)}`:''}${(a.annotations||[]).length?` · розміток: ${(a.annotations||[]).length}`:''}</span>${a.notes?`<span class="muted">Нотатка для наступного редагування: ${esc(a.notes)}</span>`:''}${assetPreview(a)}<div class="actions"><button onclick="openAsset('${esc(a.id)}')">Редагувати ресурс</button></div></div>`).join(''):'<p class="empty">Поки порожньо. Додайте ріг, Blender-сцену, референс, звук або експорт.</p>'}</article>`}
function versionPanel(){const versions=[...(active.versionHistory||[])].reverse(),count=project=>({scripts:(project.scripts||[]).length,scenes:(project.scenes||[]).length,shots:(project.scenes||[]).reduce((sum,scene)=>sum+(scene.shots||[]).length,0),lines:(project.scenes||[]).reduce((sum,scene)=>sum+(scene.dialogue||[]).length,0),assets:(project.assets||[]).length}),current=count(active),change=(before,now)=>before===now?'без змін':`${now>before?'+':''}${now-before}`;return `<article class="card full version-history"><p class="eyebrow">АВТОМАТИЧНЕ ЗБЕРЕЖЕННЯ</p><h3>Історія версій</h3><p class="muted">Перед кожною зміною програма залишає тут попередній стан проєкту. Відновлення теж створює резервну версію поточного стану — його не буде втрачено.</p><div class="version-current"><strong>Поточний стан</strong><span>${current.scripts} сценаріїв · ${current.scenes} сцен · ${current.shots} шотів · ${current.lines} реплік · ${current.assets} ресурсів</span></div>${versions.length?versions.map((version,index)=>{const snap=version.snapshot||{},saved=count(snap);return `<div class="item version-item"><strong>Версія ${versions.length-index} <span class="tag">${esc(new Date(version.createdAt).toLocaleString('uk-UA'))}</span></strong><span class="muted">${esc(version.label||'Автоматична версія')}</span><div class="version-summary"><span>Сценарії: ${saved.scripts} <b>${change(saved.scripts,current.scripts)}</b></span><span>Сцени: ${saved.scenes} <b>${change(saved.scenes,current.scenes)}</b></span><span>Шоти: ${saved.shots} <b>${change(saved.shots,current.shots)}</b></span><span>Репліки: ${saved.lines} <b>${change(saved.lines,current.lines)}</b></span><span>Ресурси: ${saved.assets} <b>${change(saved.assets,current.assets)}</b></span></div><div class="actions"><button onclick="restoreVersion('${esc(version.id)}')">Відновити цю версію</button></div></div>`}).join(''):'<p class="empty">Першу версію буде створено автоматично, щойно ви збережете будь-яку зміну.</p>'}</article>`}
function editableReference(asset){const isContactSheet=/storyboard/i.test(`${asset?.label||''} ${asset?.uri||''}`);if(!isContactSheet)return asset;return active.assets.find(item=>item.id!==asset.id&&item.type==='reference'&&typeof item.uri==='string'&&item.uri.startsWith('/')&&!/storyboard/i.test(`${item.label||''} ${item.uri||''}`))||asset}
function showReference(assetId){const selected=active.assets.find(item=>item.id===assetId),asset=editableReference(selected);if(!asset)return;const openedIndividualFrame=selected.id!==asset.id,modalEl=$('#modal');modalEl.classList.remove('focus-dialog');modalEl.classList.add('reference-dialog');$('#modal-cancel').textContent=returnToAssistantFocus?'Назад':'Скасувати';$('#modal-title').textContent=asset.label;$('#modal-fields').innerHTML=`<div class="reference-editor"><div class="reference-editor-bar"><div class="annotation-toolbar" role="toolbar" aria-label="Інструменти розмітки"><button type="button" class="annotation-tool active" data-annotation-tool="arrow" aria-label="Стрілка" title="Стрілка" onclick="setAnnotationTool('arrow')">↗</button><button type="button" class="annotation-tool" data-annotation-tool="pencil" aria-label="Олівець" title="Олівець" onclick="setAnnotationTool('pencil')">✎</button><label class="annotation-color" title="Колір позначки"><span>Колір</span><input id="annotation-color" type="color" value="${annotationColor}" onchange="setAnnotationColor(this.value)"></label><button type="button" class="annotation-undo" aria-label="Скасувати останній штрих" title="Скасувати останній штрих" onclick="undoAnnotation()">↶</button><button type="button" class="annotation-clear" aria-label="Очистити розмітку" title="Очистити розмітку" onclick="clearAnnotations()">🗑</button></div><span class="reference-mode">1 зображення для правок</span></div><figure class="reference-large"><div class="annotator-stage"><img id="reference-image" src="${esc(asset.uri)}" alt="${esc(asset.label)}"><canvas id="annotation-canvas" aria-label="Поле розмітки зображення"></canvas></div><figcaption>${asset.notes?esc(asset.notes):(openedIndividualFrame?'Відкрито окремий кадр: правки не змішуються з контактним листом.':'Позначте, що треба змінити; текстову примітку можна додати через іконку олівця.')}</figcaption></figure><div class="reference-editor-actions"><button type="button" onclick="openAssetFromReference('${esc(asset.id)}')">Редагувати ресурс</button><button type="button" class="primary" onclick="saveAnnotations('${esc(asset.id)}')">Зберегти</button></div></div>`;const form=$('#modal-form'),submit=form.querySelector('button[type="submit"]');submit.textContent='Готово';submit.removeAttribute('data-iconified');submit.removeAttribute('data-action');submit.classList.remove('icon-button');form.onsubmit=e=>{e.preventDefault();closeModal()};decorateWorkButtons(form);modalEl.showModal();setupAnnotationCanvas(asset)}
function setAnnotationTool(tool){annotationTool=tool;document.querySelectorAll('[data-annotation-tool]').forEach(button=>button.classList.toggle('active',button.dataset.annotationTool===tool))}
function setAnnotationColor(color){annotationColor=color}
function annotationPoint(event,canvas){const rect=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width)),Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height))]}
function drawAnnotation(ctx,item,width,height){const points=item.points.map(point=>[point[0]*width,point[1]*height]);if(points.length<2)return;ctx.save();ctx.strokeStyle=item.color||'#ffcc66';ctx.fillStyle=item.color||'#ffcc66';ctx.lineWidth=Math.max(3,width*.004);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);if(item.type==='pencil')points.slice(1).forEach(point=>ctx.lineTo(point[0],point[1]));else ctx.lineTo(points[points.length-1][0],points[points.length-1][1]);ctx.stroke();if(item.type==='arrow'){const from=points[0],to=points[points.length-1],angle=Math.atan2(to[1]-from[1],to[0]-from[0]),size=Math.max(12,width*.018);ctx.beginPath();ctx.moveTo(to[0],to[1]);ctx.lineTo(to[0]-size*Math.cos(angle-Math.PI/6),to[1]-size*Math.sin(angle-Math.PI/6));ctx.lineTo(to[0]-size*Math.cos(angle+Math.PI/6),to[1]-size*Math.sin(angle+Math.PI/6));ctx.closePath();ctx.fill()}ctx.restore()}
function setupAnnotationCanvas(asset){annotationItems=Array.isArray(asset.annotations)?JSON.parse(JSON.stringify(asset.annotations)):[];annotationDraft=null;const image=$('#reference-image'),canvas=$('#annotation-canvas');if(!image||!canvas)return;const redraw=()=>{const width=Math.max(1,image.clientWidth),height=Math.max(1,image.clientHeight);canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');annotationItems.forEach(item=>drawAnnotation(ctx,item,width,height));if(annotationDraft)drawAnnotation(ctx,annotationDraft,width,height)};annotationRedraw=redraw;const resize=()=>requestAnimationFrame(redraw);image.addEventListener('load',resize,{once:true});if(image.complete)resize();new ResizeObserver(resize).observe(image);canvas.onpointerdown=event=>{event.preventDefault();canvas.setPointerCapture(event.pointerId);annotationDraft={type:annotationTool,color:annotationColor,points:[annotationPoint(event,canvas)]};redraw()};canvas.onpointermove=event=>{if(!annotationDraft)return;const point=annotationPoint(event,canvas);if(annotationDraft.type==='arrow')annotationDraft.points=[annotationDraft.points[0],point];else annotationDraft.points.push(point);redraw()};canvas.onpointerup=event=>{if(!annotationDraft)return;const point=annotationPoint(event,canvas);if(annotationDraft.type==='arrow')annotationDraft.points=[annotationDraft.points[0],point];else annotationDraft.points.push(point);if(annotationDraft.points.length>1)annotationItems.push(annotationDraft);annotationDraft=null;redraw()};canvas.onpointercancel=()=>{annotationDraft=null;redraw()};redraw()}
function undoAnnotation(){annotationItems.pop();annotationRedraw?.()}
function clearAnnotations(){annotationItems=[];annotationRedraw?.()}
async function saveAnnotations(assetId){const asset=active.assets.find(item=>item.id===assetId);if(!asset)return;if(asset.status==='approved'){window.alert('Затверджений ресурс не можна змінити напряму. Створіть нову чернеткову версію в Медіабібліотеці.');return;}await api(`/api/projects/${encodeURIComponent(activeId)}/assets/${encodeURIComponent(assetId)}`,{method:'PUT',body:JSON.stringify({...asset,annotations:annotationItems})});await load(activeId);showReference(assetId)}
function openAssetFromReference(assetId){returnToAssistantFocus=true;$('#modal').close();openAsset(assetId)}
function closeModal(){const shouldReturn=returnToAssistantFocus;returnToAssistantFocus=false;$('#modal').close();$('#modal').classList.remove('focus-dialog','reference-dialog');$('#modal-cancel').textContent='Скасувати';if(shouldReturn)openAssistantFocus()}
async function restoreVersion(versionId){if(!window.confirm('Відновити цю версію? Поточний стан також буде автоматично збережено.'))return;await api(`/api/projects/${encodeURIComponent(activeId)}/versions/${encodeURIComponent(versionId)}/restore`,{method:'POST'});await load(activeId)}
function previewPanel(){const episode=(active.episodes||[]).find(item=>item.id===activeEpisodeId)||(active.episodes||[])[0],scenes=active.scenes.filter(scene=>!episode||scene.episodeId===episode.id).sort((a,b)=>Number(a.order||0)-Number(b.order||0)),shots=scenes.flatMap(scene=>scene.shots||[]),lines=scenes.flatMap(scene=>scene.dialogue||[]),totalSeconds=scenes.reduce((total,scene)=>total+Number(scene.durationSeconds||0),0),readyScenes=scenes.filter(scene=>scene.status==='approved'||scene.status==='production').length,visualReady=shots.filter(shot=>shot.imagePrompt&&(shot.referenceAssetIds||[]).length).length,audioReady=lines.filter(line=>(line.textUk||(line.language==='uk'&&line.text))&&line.estimatedSeconds).length;const sceneCards=scenes.map((scene,index)=>{const sceneShots=scene.shots||[],sceneLines=scene.dialogue||[],hasVisuals=sceneShots.length&&sceneShots.every(shot=>shot.imagePrompt),hasAudio=!sceneLines.length||sceneLines.every(line=>(line.textUk||(line.language==='uk'&&line.text))&&line.estimatedSeconds);return `<div class="item assembly-scene"><strong>${index+1}. ${esc(scene.title)} <span class="tag">${esc(scene.durationSeconds)} с</span></strong><span class="muted">Кадри: ${sceneShots.length} ${hasVisuals?'✓':'· потрібен опис'} · Репліки: ${sceneLines.length} ${hasAudio?'✓':'· заповнити текст/тривалість'} · Стан: ${esc(label('status',scene.status||'draft'))}</span><div class="actions"><button onclick="selectSceneForDesk('${scene.id}');goToView('storyboard')">Відкрити кадри</button><button onclick="checkProduction({sceneId:'${scene.id}'})">Перевірити</button></div></div>`}).join('')||'<p class="empty">Додайте сцени у кроці «1. Сценарій», щоб зібрати план монтажу.</p>';return `<article class="card full assembly-plan"><p class="eyebrow">КРОК 4 · ЗБІРКА</p><h3>Передмонтажна перевірка</h3><p class="muted">Тут видно, що вже підготовлено для майбутньої збірки. Це не монтаж і не фінальне відео: студія лише допомагає не загубити незавершені частини.</p><div class="metrics"><div class="metric"><b>${scenes.length}</b>сцен</div><div class="metric"><b>${shots.length}</b>шотів</div><div class="metric"><b>${lines.length}</b>реплік</div><div class="metric"><b>${totalSeconds} с</b>загальний план</div></div><div class="assembly-status"><div><strong>Відеоряд</strong><span>${visualReady}/${shots.length} шотів мають опис і референси</span></div><div><strong>Аудіо</strong><span>${audioReady}/${lines.length} реплік мають текст і тривалість</span></div><div><strong>Сцени</strong><span>${readyScenes}/${scenes.length} мають ручний статус готовності</span></div></div><div class="actions"><button onclick="goToView('storyboard')">Працювати з кадрами</button><button onclick="goToView('audio')">Працювати з аудіо</button></div></article><article class="card full"><h3>Сцени перед збиранням</h3>${sceneCards}</article><article class="card full"><p class="eyebrow">ТЕСТОВІ МАТЕРІАЛИ · ЧЕРНЕТКИ</p><h3>Візуальна перевірка</h3><p class="muted">Ці зображення лишаються прикладами робочого напряму, а не фінальними кадрами або затвердженим творчим рішенням.</p><div class="preview-layout"><section><h4>Вступний кадр</h4><img class="preview-image" src="/assets/test-animatic/luma-prelude-draft-v1.png" alt="Чернетковий вступний кадр: Лума на вечірній стежці біля згаслого ліхтарика"><p class="muted">Робочий референс для перевірки атмосфери.</p></section><section><h4>Поточна розкадровка</h4><img class="preview-image" src="/assets/storyboards/vohnyk-dlia-druha-storyboard-draft-v1.png" alt="Чернеткова розкадровка трьох сцен"><p class="muted">Робоча послідовність трьох сцен.</p></section></div></article>`}
function profileCard(){const p=active.profile;const entries=[['Аудиторія',p.audience],['Формат',p.format],['Тон',p.tone],['Сезонна арка',p.seasonArc],['Власник затверджень',p.approvalOwner]].filter(([,value])=>value),manifest=[['Місія',p.mission],['Духовна основа',p.gospelFoundation],['Творча свобода',p.creativeApproach],['Обіцянка глядачеві',p.audiencePromise]].filter(([,value])=>value);return `<article class="card full"><h3>Паспорт проєкту <button class="scene-actions" title="Редагувати паспорт" onclick="openProfile()">✎</button></h3>${entries.length?entries.map(([name,value])=>`<div class="item"><strong>${name}</strong><span class="muted">${esc(value)}</span></div>`).join(''):'<p class="empty">Зафіксуйте аудиторію, формат, тон, правила й сезонну арку перед роботою зі сценарієм.</p>'}${manifest.length?`<details class="creative-manifest"><summary>Творчий маніфест проєкту</summary>${manifest.map(([name,value])=>`<div><strong>${name}</strong><p>${esc(value)}</p></div>`).join('')}</details>`:''}</article>`}
function workflowBoard(){return `<article class="card full"><h3>Дошка виробництва</h3><div class="workflow">${active.workflow.map(s=>`<button class="stage ${esc(s.status)}" onclick="openStage('${esc(s.id)}')"><strong>${esc(label('workflow',s.id))}</strong><span>${esc(label('workflowStatus',s.status))}</span>${s.note?`<small>${esc(s.note)}</small>`:''}</button>`).join('')}</div></article>`}
function storyboardWorkspace(){const scenes=[...active.scenes].sort((a,b)=>Number(a.order||0)-Number(b.order||0));if(!scenes.length)return `<article class="card full" id="storyboard-editor"><h3>Сцени та кадри</h3><p class="muted">Сцена — маленька подія історії. Кадр — безперервний погляд камери всередині сцени.</p><p class="empty">Створіть першу сцену, щоб зібрати подію, кадри, репліки й тривалість в одному місці.</p><button class="primary" onclick="openScene()">＋ Створити першу сцену</button></article>`;const scene=scenes.find(item=>item.id===activeSceneId)||scenes[0],shots=scene.shots||[],shot=shots.find(item=>item.id===activeShotId)||shots[0],episode=(active.episodes||[]).find(item=>item.id===scene.episodeId),characters=(scene.characterIds||[]).map(id=>active.bibles.characters.find(character=>character.id===id)?.name).filter(Boolean);const imageAsset=shot&&(shot.referenceAssetIds||[]).map(id=>active.assets.find(asset=>asset.id===id)).find(asset=>asset?.uri?.startsWith('/'));const lines=scene.dialogue||[];return `<article class="card full storyboard-workspace" id="storyboard-editor"><div class="storyboard-title"><div><p class="eyebrow">РЕЖИСЕРСЬКИЙ РОБОЧИЙ СТІЛ</p><h3>Сцени та кадри</h3><p class="muted">Оберіть сцену, потім кадр. Праворуч — все, що потрібно для перевірки його змісту.</p></div><div class="actions"><button onclick="openScene('', '${scene.id}')">Редагувати сцену</button><button class="primary" onclick="openShot('${scene.id}')">＋ Кадр</button></div></div><div class="director-desk"><section class="desk-scenes"><div class="desk-label">СЦЕНИ ВИПУСКУ</div>${scenes.map((item,index)=>`<button class="desk-scene ${item.id===scene.id?'selected':''}" onclick="selectSceneForDesk('${item.id}')"><span>${index+1}</span><strong>${esc(item.title)}</strong><small>${item.durationSeconds} с · ${(item.shots||[]).length} кадрів · ${(item.dialogue||[]).length} реплік</small></button>`).join('')}<button class="desk-add" onclick="openScene('${scene.episodeId||''}')">＋ Додати сцену</button></section><section class="desk-canvas"><div class="canvas-meta"><span>Сцена ${esc(scene.order||'—')} · ${esc(episode?.title||'без випуску')}</span><span class="tag">${esc(label('status',scene.status))}</span></div>${shot?`<div class="shot-screen">${imageAsset?`<img src="${esc(imageAsset.uri)}" alt="Референс для кадру">`:''}<div class="shot-overlay"><span>Кадр ${shots.indexOf(shot)+1} · ${esc(shot.seconds)} с</span><strong>${esc(shot.imagePrompt||shot.prompt||'Додайте опис ключового кадру')}</strong></div></div><div class="shot-strip">${shots.map((item,index)=>`<button class="shot-thumb ${item.id===shot.id?'selected':''}" onclick="selectShotForDesk('${scene.id}','${item.id}')"><span>${index+1}</span><strong>${esc(item.seconds)} с</strong><small>${esc(item.camera||'камера не задана')}</small></button>`).join('')}</div>`:`<div class="empty-shot"><strong>У сцені ще немає кадрів</strong><span>Додайте перший кадр: опишіть композицію, дію, рух камери та світло.</span><button class="primary" onclick="openShot('${scene.id}')">＋ Додати перший кадр</button></div>`}<div class="canvas-actions"><button onclick="checkProduction({sceneId:'${scene.id}'})">Перевірити сцену</button><button onclick="openDialogue('${scene.id}')">＋ Репліка</button></div></section><aside class="desk-inspector"><div class="desk-label">ЩО В КАДРІ</div>${shot?`<h4>Кадр ${shots.indexOf(shot)+1}</h4><div class="inspect-row"><span>Камера</span><strong>${esc(shot.camera||'не задано')}</strong></div><div class="inspect-row"><span>Рух</span><strong>${esc(shot.motionPrompt||'не задано')}</strong></div><div class="inspect-row"><span>Світло</span><strong>${esc(shot.lighting||'не задано')}</strong></div><div class="inspect-row"><span>Стан</span><strong>${esc(label('status',shot.status||'draft'))}</strong></div><button onclick="openShot('${scene.id}','${shot.id}')">Редагувати кадр</button>`:'<p class="empty">Додайте кадр, щоб описати його режисерські параметри.</p>'}<div class="scene-purpose"><span>Мета сцени</span><p>${esc(scene.purpose||'Ще не описано, навіщо ця сцена історії.')}</p></div><div class="scene-characters"><span>Персонажі</span><p>${esc(characters.join(', ')||'Не вибрано')}</p></div><div class="dialogue-preview"><span>Репліки сцени · ${lines.length}</span>${lines.length?lines.map(line=>`<button onclick="openDialogue('${scene.id}','${line.id}')"><strong>${esc(active.bibles.characters.find(character=>character.id===line.characterId)?.name||'Персонаж')}</strong><small>UA: ${esc(line.textUk||(line.language==='uk'?line.text:'—'))}</small><small>EN: ${esc(line.textEn||(line.language==='en'?line.text:'—'))}</small></button>`).join(''):'<p>Поки немає реплік.</p>'}</div></aside></div></article>`}
function episodePanel(){const episodes=[...(active.episodes||[])].sort((a,b)=>a.seasonNumber-b.seasonNumber||a.episodeNumber-b.episodeNumber);const selected=episodes.find(item=>item.id===activeEpisodeId);return `<article class="card full" id="episodes"><h3>План сезону <button class="scene-actions" onclick="openEpisode()">＋</button></h3>${episodes.length?episodes.map(episode=>{const scenes=active.scenes.filter(scene=>scene.episodeId===episode.id),seconds=scenes.reduce((total,scene)=>total+Number(scene.durationSeconds||0),0);return `<div class="item"><strong>Сезон ${episode.seasonNumber} · Випуск ${episode.episodeNumber}: ${esc(episode.title)} <span class="tag">${episode.targetMinutes} хв</span></strong><span class="muted">${esc(episode.logline||'Логлайн ще не задано')} · ${esc(label('status',episode.status))} · ${scenes.length} сцен · ${seconds} с у плані</span><div class="actions"><button onclick="openEpisodeEditor('${episode.id}')">Відкрити редактор</button><button onclick="openEpisode('${episode.id}')">Параметри</button><button onclick="openScene('${episode.id}')">＋ Сцена</button></div></div>`}).join(''):'<p class="empty">Створіть перший випуск. Для серіалу це дає спільну структуру сезону, а для одиничного ролика — зрозумілий контейнер для сценарію та сцен.</p>'}</article>${selected?episodeEditor(selected):''}`}
function episodeEditor(episode){const scenes=active.scenes.filter(scene=>scene.episodeId===episode.id),seconds=scenes.reduce((total,scene)=>total+Number(scene.durationSeconds||0),0),shots=scenes.reduce((total,scene)=>total+(scene.shots||[]).length,0),lines=scenes.flatMap(scene=>scene.dialogue||[]),missingUk=lines.filter(line=>!(line.textUk||(line.language==='uk'&&line.text))).length,missingEn=lines.filter(line=>!(line.textEn||(line.language==='en'&&line.text))).length,targetSeconds=Number(episode.targetMinutes)*60;return `<article class="card full" id="episode-editor"><h3>Редактор випуску: ${esc(episode.title)} <button class="scene-actions" onclick="closeEpisodeEditor()">Закрити</button></h3><p class="muted">Чернетковий робочий план. Творчий зміст не вважається затвердженим, доки статус випуску або відповідних записів не змінено вручну.</p><div class="metrics"><div class="metric"><b>${scenes.length}</b>сцен</div><div class="metric"><b>${shots}</b>шотів</div><div class="metric"><b>${seconds} / ${targetSeconds} с</b>план / ціль</div></div><div class="item"><strong>Мовна готовність реплік</strong><span class="muted">UA без тексту: ${missingUk} · EN без тексту: ${missingEn} · усього реплік: ${lines.length}</span></div>${scenes.length?scenes.map((scene,index)=>{const sceneShots=scene.shots||[],sceneLines=scene.dialogue||[],complete=sceneLines.filter(line=>(line.textUk||(line.language==='uk'&&line.text))&&(line.textEn||(line.language==='en'&&line.text))).length;return `<div class="item"><strong>${index+1}. ${esc(scene.title)} <span class="tag">${scene.durationSeconds} с</span></strong><span class="muted">${esc(scene.purpose||'Драматична мета не задана')} · ${sceneShots.length} шотів · UA/EN готові: ${complete}/${sceneLines.length}</span><div class="actions"><button onclick="checkProduction({sceneId:'${scene.id}'})">Перевірити сцену</button><button onclick="openScene('', '${scene.id}')">Редагувати сцену</button><button onclick="openShot('${scene.id}')">＋ Шот</button><button onclick="openDialogue('${scene.id}')">＋ Репліка</button></div></div>`}).join(''):'<p class="empty">У випуску ще немає сцен. Додайте першу сцену, щоб зібрати таймінг, шоти та репліки.</p>'}<div class="actions"><button onclick="checkProduction({episodeId:'${episode.id}'})">Перевірити випуск</button><button onclick="openScene('${episode.id}')">＋ Додати сцену</button><button onclick="openEpisode('${episode.id}')">Редагувати параметри випуску</button></div></article>`}
function scriptPanel(){const all=active.scripts||[],ordered=list=>[...list].sort((a,b)=>Number(a.order||0)-Number(b.order||0)||String(a.createdAt||'').localeCompare(String(b.createdAt||''))),visible=ordered(all.filter(item=>!item.deletedAt&&item.visibility!=='hidden')),hidden=ordered(all.filter(item=>!item.deletedAt&&item.visibility==='hidden')),trash=ordered(all.filter(item=>item.deletedAt)),card=(script,index,mode='visible')=>`<article class="script-document"><div class="script-document-number">${mode==='visible'?index+1:'—'}</div><div class="script-document-copy"><strong>${esc(script.title)} <span class="tag">v${esc(script.version)}</span></strong><p>${esc(script.logline||'Без логлайну')}</p><span>${esc(label('status',script.status))}${mode==='trash'&&script.purgeAfter?` · збережено щонайменше до ${new Date(script.purgeAfter).toLocaleDateString('uk-UA')}`:''}</span></div><div class="script-document-actions">${mode==='visible'?`<button title="Вище" onclick="reorderScript('${esc(script.id)}',-1)" ${index===0?'disabled':''}>↑</button><button title="Нижче" onclick="reorderScript('${esc(script.id)}',1)" ${index===visible.length-1?'disabled':''}>↓</button><button onclick="openScript('${esc(script.id)}')">Редагувати</button><button title="Приховати сценарій" onclick="setScriptVisibility('${esc(script.id)}','hidden')">◉ Сховати</button><button class="danger-action" title="Перемістити до кошика" onclick="trashScript('${esc(script.id)}')">⌫</button>`:mode==='hidden'?`<button onclick="openScript('${esc(script.id)}')">Редагувати</button><button onclick="setScriptVisibility('${esc(script.id)}','visible')">◉ Показати</button><button class="danger-action" onclick="trashScript('${esc(script.id)}')">⌫ До кошика</button>`:`<button class="primary" onclick="restoreScript('${esc(script.id)}')">↶ Відновити</button>`}</div></article>`;return `<article class="card full" id="script-editor"><div class="script-library-head"><div><p class="eyebrow">ДОКУМЕНТИ ПРОЄКТУ</p><h3>Сценарії</h3><p class="muted">Порядок, видимість і кошик належать документам сценарію — сцени всередині них не змінюються.</p></div><button class="primary" onclick="openScript()">＋ Сценарій</button></div><section class="script-library"><p class="script-library-label">РОБОЧІ СЦЕНАРІЇ · ${visible.length}</p>${visible.length?visible.map((script,index)=>card(script,index)).join(''):'<p class="empty">Тут немає видимих сценаріїв. Відновіть документ із прихованих або створіть новий.</p>'}</section><details class="script-library-fold" ${hidden.length?'':'hidden'}><summary>Приховані сценарії · ${hidden.length}</summary><p class="muted">Вони не заважають у робочому списку, але залишаються у проєкті.</p>${hidden.map(script=>card(script,0,'hidden')).join('')}</details><details class="script-library-fold trash" ${trash.length?'':'hidden'}><summary>Кошик · ${trash.length}</summary><p class="muted">Видалені документи зберігаються в кошику щонайменше 30 днів.</p>${trash.map(script=>card(script,0,'trash')).join('')}</details></article>`}
function voicePanel(){const voices=active.voiceProfiles||[],episode=(active.episodes||[]).find(item=>item.id===activeEpisodeId)||(active.episodes||[])[0],scenes=active.scenes.filter(scene=>!episode||scene.episodeId===episode.id).sort((a,b)=>Number(a.order||0)-Number(b.order||0)),lines=scenes.flatMap(scene=>(scene.dialogue||[]).map(line=>({scene,line,character:active.bibles.characters.find(character=>character.id===line.characterId),voice:voices.find(profile=>profile.identityKey===line.voiceIdentityKey)}))),total=lines.reduce((sum,item)=>sum+Number(item.line.estimatedSeconds||0),0),episodeTitle=episode?`Випуск: ${esc(episode.title)}.`:'Виберіть випуск, щоб працювати з його репліками.',lineMarkup=lines.map(({scene,line,character,voice},index)=>`<article class="audio-line"><div class="audio-index">${index+1}</div><div class="audio-copy"><div class="audio-meta"><span>${esc(scene.title)}</span><strong>${esc(character?.name||'Персонаж не знайдений')}</strong><span class="tag">${esc(line.estimatedSeconds||1)} с</span><span class="tag">${esc(label('status',line.status||'draft'))}</span></div><p>${esc(line.textUk||line.text||'Українська репліка ще не написана')}</p>${line.textEn?`<p class="audio-translation">EN: ${esc(line.textEn)}</p>`:''}${line.emotion?`<small><b>Емоція:</b> ${esc(line.emotion)}</small>`:''}${line.performanceNote?`<small><b>Примітка:</b> ${esc(line.performanceNote)}</small>`:''}${voice?`<button class="audio-voice-settings" onclick="openVoiceProfile('${esc(voice.id)}')">⚙ Налаштувати голос: ${esc(voice.name)}</button>`:`<small class="audio-missing-profile">Для цієї репліки ще не знайдено голосовий профіль.</small>`}</div><button onclick="openDialogue('${esc(scene.id)}','${esc(line.id)}')">Редагувати</button></article>`).join(''),planBody=lineMarkup?`<div class="audio-lines">${lineMarkup}</div>`:`<div class="empty"><p>У цьому випуску ще немає реплік.</p><button class="primary" onclick="goToView('script')">Перейти до сценарію</button></div>`,voiceMarkup=voices.map(voice=>`<div class="item"><strong>${esc(voice.name)} <span class="tag">${esc(label('status',voice.status))}</span></strong><span class="muted">${esc(label('age',voice.ageBand))} · ${esc(voice.languages.map(code=>label('language',code)).join(' / '))} · ${esc(voice.engine)}</span><span class="muted">ID: ${esc(voice.identityKey)} · Ліцензія: ${esc(voice.license)}</span><div class="actions"><button onclick="openVoiceProfile('${esc(voice.id)}')">Редагувати голос</button></div></div>`).join('')||'<p class="empty">Створіть голосовий профіль для стабільного голосу персонажа або диктора.</p>';return `<article class="card full audio-plan"><div class="route-head"><div><p class="eyebrow">КРОК 3 · АУДІО</p><h3>План аудіодоріжки</h3><p class="muted">${episodeTitle} Тут редагується текст і режисерська задача для кожної репліки.</p></div><span class="tag">${lines.length} реплік · ${total} с тексту</span></div><div class="audio-guide"><strong>Що тут робити:</strong> перевірте слова, вкажіть емоцію і темп, додайте примітку для виконання. Аудіофайли з’являться тут після підключення генератора голосу.</div>${planBody}</article><article class="card full" id="voice-profiles"><p class="eyebrow">ПРОФІЛІ ГОЛОСІВ</p><h3>Як мають звучати персонажі</h3><p class="muted">Тут зберігається характер і технічні налаштування голосу. Зміни застосуються до наступних створених дублів.</p>${voiceMarkup}</article>`}
function localizationPanel(){const versions=active.localizations||[];return `<article class="card full"><h3>Мовні версії та доріжки <button class="scene-actions" onclick="openLocalization()">＋</button></h3>${versions.length?versions.map(version=>`<div class="item"><strong>${esc(label('language',version.language))} <span class="tag">${esc(label('status',version.status))}</span></strong><span class="muted">Відеоряд: ${version.videoMasterUri?'є':'не задано'} · голос: ${version.voiceStemUri?'є':'не задано'} · музика: ${version.musicStemUri?'є':'не задано'} · SFX: ${version.sfxStemUri?'є':'не задано'} · субтитри: ${version.subtitlesUri?'є':'не задано'}</span><button onclick="openLocalization('${version.id}')">Редагувати</button></div>`).join(''):'<p class="empty">Додайте український оригінал або англійський дубляж. Video master зберігається один раз, а кожна мова має власні stems і субтитри.</p>'}</article>`}
function productionPanel(){const manifests=active.productions||[];return `<article class="card full"><h3>Production manifests</h3>${manifests.length?manifests.map(manifest=>`<div class="item"><strong>Сцена: ${esc(active.scenes.find(scene=>scene.id===manifest.sceneId)?.title||manifest.sceneId)} <span class="tag">готово для worker</span></strong><span class="muted">Затвердив: ${esc(manifest.approvedBy)} · ${new Date(manifest.approvedAt).toLocaleString('uk-UA')}</span><div class="actions"><button onclick="downloadManifest('${manifest.id}')">Завантажити JSON</button><button onclick="queueRender('${manifest.id}')">Поставити рендер у чергу</button></div></div>`).join(''):'<p class="empty">Створіть і затвердьте production manifest зі сцени після успішної перевірки готовності.</p>'}</article>`}
function productionReviewPanel(){const scenes=active.scenes||[],approved=scenes.filter(scene=>['approved','production'].includes(scene.status)).length,shotIssues=scenes.filter(scene=>(scene.shots||[]).some(shot=>shot.status!=='approved')).length,lines=scenes.flatMap(scene=>scene.dialogue||[]),unapprovedLines=lines.filter(line=>line.status!=='approved').length,continuityIssues=(continuity?.issues||[]).length;return `<article class="card full"><h3>Production review</h3><p class="muted">Огляд фактів перед ручним затвердженням. Він не змінює статусів автоматично.</p><div class="metrics"><div class="metric"><b>${approved}/${scenes.length}</b>сцен затверджено</div><div class="metric"><b>${shotIssues}</b>сцен із незатвердженими шотами</div><div class="metric"><b>${unapprovedLines}</b>реплік не затверджено</div></div><div class="item"><strong>Консистентність assets</strong><span class="muted">Попереджень: ${continuityIssues}. Перед manifest перевірте сцену окремо: система покаже блокувальні умови.</span></div><div class="actions"><button onclick="validate()">Перевірити весь проєкт</button></div></article>`}
function renderQueuePanel(){const jobs=active.renderJobs||[];return `<article class="card full"><h3>Черга GPU-рендерів</h3>${jobs.length?jobs.map(job=>`<div class="item"><strong>${esc(job.target)} <span class="tag">${esc(job.status)}</span></strong><span class="muted">Пріоритет: ${esc(job.priority)} · ${esc(job.note)}</span></div>`).join(''):'<p class="empty">Черга порожня. Локальна програма лише готує завдання; Blender і важкі моделі працюватимуть на окремому GPU worker.</p>'}</article>`}
function continuityPanel(){const report=continuity||{issues:[],scenes:[]};return `<article class="card full"><h3>Інспектор консистентності assets <button class="scene-actions" onclick="load()">Оновити</button></h3>${!report.scenes.length?'<p class="empty">Створіть сцену й прив’яжіть resources до її шотів, щоб перевірити консистентність.</p>':`${report.scenes.map(scene=>`<div class="item"><strong>${esc(scene.title)}</strong><span class="muted">Використано resources: ${scene.usedAssetIds.length}</span>${scene.characterChecks.map(check=>`<span class="muted">${esc(check.characterName)}: ${check.referenced?'референс у шоті':'референс не використано'} (${check.linkedAssetCount} затверджених assets)</span>`).join('')}</div>`).join('')}${report.issues.length?report.issues.map(issue=>`<div class="item warning"><strong>${esc(issue.code)}</strong><span class="muted">${esc(issue.message)}</span></div>`).join(''):'<p class="ok">✓ Поточні scenes не мають continuity-попереджень.</p>'}`}</article>`}
function listBible(items,kind){return items.length?items.map(i=>`<div class="item"><strong>${esc(i.name)} <span class="tag">v${esc(i.version)}</span></strong><span class="muted">${esc(label('status',i.status))}${kind==='characters'?` · ${esc(label('age',i.ageBand))} · ${esc(i.role||'роль не задано')} · ${esc(i.identityKey||'ідентифікатор голосу не задано')}`:''}</span>${kind==='characters'&&i.appearance?`<span class="muted">Зовнішність: ${esc(i.appearance)}</span>`:''}<button onclick="openBible('${kind}','${i.id}')">Редагувати</button></div>`).join(''):'<p class="empty">Додайте версійний запис.</p>'}
function listScenes(){return active.scenes.length?active.scenes.map(s=>{const episode=(active.episodes||[]).find(item=>item.id===s.episodeId);return `<div class="item"><strong>${esc(s.title)} <span class="tag">${s.durationSeconds} с</span></strong><span class="muted">${episode?`С${episode.seasonNumber} · В${episode.episodeNumber}: ${esc(episode.title)} · `:''}${esc(s.purpose||'Без опису')} · ${s.shots.length} шотів · ${s.dialogue.length} реплік · ${label('status',s.status)}</span><div class="actions"><button onclick="openScene('', '${s.id}')">Редагувати сцену</button><button onclick="openShot('${s.id}')">＋ Шот</button><button onclick="openDialogue('${s.id}')">＋ Репліка</button><button onclick="createManifest('${s.id}')">Manifest</button></div><details class="shots"><summary>Розкадрування (${s.shots.length})</summary>${s.shots.map((shot,index)=>`<div class="shot"><strong>Шот ${index+1} · ${shot.seconds} с · ${esc(shot.camera)}</strong><span class="muted">Ключовий кадр: ${esc(shot.imagePrompt||shot.prompt||'не задано')}</span><span class="muted">Рух: ${esc(shot.motionPrompt||'не задано')} · Світло: ${esc(shot.lighting||'не задано')}</span><span class="muted">Референси: ${(shot.referenceAssetIds||[]).length} · ${label('status',shot.status||'draft')}</span><button onclick="openShot('${s.id}','${shot.id}')">Редагувати шот</button></div>`).join('')}<div class="shot"><strong>Репліки (${s.dialogue.length})</strong>${s.dialogue.map(line=>`<div class="item"><strong>${esc(active.bibles.characters.find(c=>c.id===line.characterId)?.name||'Персонаж')}</strong><span class="muted">UA: ${esc(line.textUk|| (line.language==='uk'?line.text:'—'))}</span><span class="muted">EN: ${esc(line.textEn|| (line.language==='en'?line.text:'—'))}</span><button onclick="openDialogue('${s.id}','${line.id}')">Редагувати репліку</button></div>`).join('')||'<p class="empty">Реплік ще немає.</p>'}</div></details></div>`}).join(''):'<p class="empty">Сцен ще немає. Сцена містить персонажів, шоти, репліки, запити та історію рендерів.</p>'}
function modal(title,fields,handler){$('#modal').classList.remove('focus-dialog','project-wizard-dialog');$('#modal-cancel').textContent=returnToAssistantFocus?'Назад до режиму фокусу':'Скасувати';$('#modal-title').textContent=title;$('#modal-fields').innerHTML=fields;const form=$('#modal-form'),submit=form.querySelector('button[type="submit"]');submit.textContent='Зберегти';form.onsubmit=async e=>{e.preventDefault();try{await handler(new FormData(form));const shouldReturn=returnToAssistantFocus;returnToAssistantFocus=false;$('#modal').close();await load();if(shouldReturn)openAssistantFocus()}catch(err){alert(err.message)}};$('#modal').showModal()}
function openProfile(){const p=active.profile;modal('Паспорт проєкту',`<label>Аудиторія<textarea name="audience" placeholder="Для кого створюється відео">${esc(p.audience)}</textarea></label><label>Формат<textarea name="format" placeholder="Тривалість, платформа, формат серіалу або роликів">${esc(p.format)}</textarea></label><label>Тон<textarea name="tone" placeholder="Наприклад: теплий, чесний, пригодницький">${esc(p.tone)}</textarea></label><fieldset><legend>Творчий маніфест</legend><p class="muted">Це орієнтир для плану сезону та AI Помічника проєкту. Він не замінює ручного творчого рішення.</p><label>Місія<textarea name="mission" placeholder="Навіщо існує канал і що він хоче відкрити глядачеві">${esc(p.mission||'')}</textarea></label><label>Духовна основа<textarea name="gospelFoundation" placeholder="Незмінний зміст, який мають берегти історії">${esc(p.gospelFoundation||'')}</textarea></label><label>Творча свобода<textarea name="creativeApproach" placeholder="Якими світами, героями й жанрами можна це показувати">${esc(p.creativeApproach||'')}</textarea></label><label>Обіцянка глядачеві<textarea name="audiencePromise" placeholder="Яким має бути досвід перегляду">${esc(p.audiencePromise||'')}</textarea></label></fieldset><label>Редакційні правила<textarea name="editorialRules" placeholder="Обов’язкові принципи для сценарію та візуалу">${esc(p.editorialRules)}</textarea></label><label>Заборони / межі<textarea name="exclusions" placeholder="Чого уникати">${esc(p.exclusions)}</textarea></label><label>Сезонна арка<textarea name="seasonArc" placeholder="Спільний розвиток епізодів">${esc(p.seasonArc)}</textarea></label><label>Власник затверджень<input name="approvalOwner" value="${esc(p.approvalOwner)}" placeholder="Ім’я або роль"></label>`,f=>api(`/api/projects/${encodeURIComponent(activeId)}/profile`,{method:'PUT',body:JSON.stringify(Object.fromEntries(f))}))}
function openScript(scriptId,initial={}){const script=scriptId?(active.scripts||[]).find(item=>item.id===scriptId):{title:'',episodeId:activeEpisodeId||'',logline:'',body:'',status:'draft',...initial};const episodes=active.episodes||[];modal(scriptId?'Редагувати сценарій':'Нова сценарна чернетка',`<label>Випуск<select name="episodeId"><option value="">— загальний сценарний документ —</option>${episodes.map(episode=>`<option value="${esc(episode.id)}" ${script.episodeId===episode.id?'selected':''}>Сезон ${episode.seasonNumber} · Випуск ${episode.episodeNumber}: ${esc(episode.title)}</option>`).join('')}</select></label><label>Назва<input name="title" required value="${esc(script.title)}" placeholder="Робоча назва сценарію"></label><label>Логлайн<textarea name="logline" placeholder="Одне-два речення про центральний конфлікт і зміни героя">${esc(script.logline||'')}</textarea></label><label>Текст сценарію<textarea name="body" required placeholder="Сцени, дія, діалоги й режисерські примітки…">${esc(script.body||'')}</textarea></label><label>Стан<select name="status"><option value="draft" ${script.status==='draft'?'selected':''}>Чернетка</option><option value="in-review" ${script.status==='in-review'?'selected':''}>На перевірці</option><option value="approved" ${script.status==='approved'?'selected':''}>Затверджено</option></select></label>`,f=>api(`/api/projects/${encodeURIComponent(activeId)}/scripts${scriptId?`/${scriptId}`:''}`,{method:scriptId?'PUT':'POST',body:JSON.stringify(Object.fromEntries(f))}))}
function openEpisodeEditor(episodeId){activeEpisodeId=episodeId;render();document.getElementById('episode-editor')?.scrollIntoView({behavior:'smooth',block:'start'})}
function closeEpisodeEditor(){activeEpisodeId=null;render()}
function openEpisode(episodeId){const nextNumber=(active.episodes||[]).filter(item=>item.seasonNumber===1).length+1;const episode=episodeId?(active.episodes||[]).find(item=>item.id===episodeId):{title:'',logline:'',theme:'',seasonNumber:1,episodeNumber:nextNumber,targetMinutes:active.targetMinutes,status:'idea'};modal(episodeId?'Редагувати випуск':'Новий випуск',`<label>Назва випуску<input name="title" required value="${esc(episode.title)}" placeholder="Робоча назва випуску"></label><label>Основна думка<textarea name="theme" placeholder="Яку просту людську думку має відчути глядач?">${esc(episode.theme||'')}</textarea></label><label>Логлайн<textarea name="logline" placeholder="Самостійна історія випуску та зміна героя">${esc(episode.logline||'')}</textarea></label><label>Номер сезону<input name="seasonNumber" type="number" min="1" required value="${episode.seasonNumber}"></label><label>Номер випуску<input name="episodeNumber" type="number" min="1" required value="${episode.episodeNumber}"></label><label>Цільова тривалість, хв<input name="targetMinutes" type="number" min="1" required value="${episode.targetMinutes}"></label><label>Стан<select name="status"><option value="idea" ${episode.status==='idea'?'selected':''}>Ідея</option><option value="development" ${episode.status==='development'?'selected':''}>Розробка</option><option value="approved" ${episode.status==='approved'?'selected':''}>Затверджено</option><option value="production" ${episode.status==='production'?'selected':''}>Виробництво</option><option value="released" ${episode.status==='released'?'selected':''}>Випущено</option></select></label>`,f=>api(`/api/projects/${encodeURIComponent(activeId)}/episodes${episodeId?`/${episodeId}`:''}`,{method:episodeId?'PUT':'POST',body:JSON.stringify(Object.fromEntries(f))}))}
function openVoiceProfile(voiceId){const voice=voiceId?(active.voiceProfiles||[]).find(item=>item.id===voiceId):{name:'',identityKey:'',ageBand:'adult',languages:['uk'],engine:'Piper · uk_UA-tetiana-high',license:'Piper voice model · перевірити умови перед публікацією',notes:'',generationSettings:{stability:.5,similarityBoost:.75,style:0,speed:1,sentenceSilence:.2,volume:1,outputFormat:'wav',speakerBoost:true},status:'draft'},settings={stability:.5,similarityBoost:.75,style:0,speed:1,sentenceSilence:.2,volume:1,outputFormat:'wav',speakerBoost:true,...(voice.generationSettings||{})};modal(voiceId?'Налаштування голосу':'Новий голосовий профіль',`<div class="voice-settings-intro"><p class="eyebrow">ПРОФІЛЬ ГОЛОСУ</p><p>Налаштування застосуються до всіх нових пробних озвучок цього профілю. Вже створені файли не змінюються.</p></div><label>Назва<input name="name" required value="${esc(voice.name)}" placeholder="Наприклад: Голос Луми — українська"></label><label>Ключ ідентичності<input name="identityKey" required value="${esc(voice.identityKey)}" placeholder="luma-uk-v1"></label><label>Вікова категорія<select name="ageBand">${['child','teen','young-adult','adult','elder'].map(age=>`<option value="${age}" ${voice.ageBand===age?'selected':''}>${label('age',age)}</option>`).join('')}</select></label><fieldset><legend>Мова</legend><label class="check"><input type="checkbox" name="language" value="uk" ${(voice.languages||[]).includes('uk')?'checked':''}> Українська</label><label class="check"><input type="checkbox" name="language" value="en" ${(voice.languages||[]).includes('en')?'checked':''}> Англійська <small>Для локального Piper поки доступна лише українська.</small></label></fieldset><label>Модель / двигун<input name="engine" required value="${esc(voice.engine)}" placeholder="Piper · uk_UA-tetiana-high"></label><label>Ліцензія<input name="license" required value="${esc(voice.license)}" placeholder="Умови використання голосу"></label><fieldset class="voice-settings"><legend>Налаштування звучання</legend><p class="muted">Для Piper реально впливають темп, стабільність, виразність, пауза й гучність. «Схожість» та «Підсилення голосу» збережено для майбутнього сумісного TTS.</p>${voiceSlider('speed','Швидкість','Повільніше','Швидше',settings.speed,'1.00 — природний вихідний темп.',.7,1.2,.05)}${voiceSlider('stability','Стабільність','Більше варіативності','Більш рівно',settings.stability,'Вища стабільність зменшує випадкову варіативність Piper.',0,1,.05)}${voiceSlider('similarityBoost','Схожість із голосом','Низька','Висока',settings.similarityBoost,'Збережеться для зовнішнього TTS; локальна модель має один фіксований голос.',0,1,.05)}${voiceSlider('style','Виразність стилю','Стримано','Виразніше',settings.style,'Змінює варіативність ритму; почніть із 0.15–0.35.',0,1,.05)}${voiceSlider('sentenceSilence','Пауза між реченнями','Без паузи','Довша пауза',settings.sentenceSilence,'У секундах. Для живого діалогу зазвичай достатньо 0.15–0.30.',0,1.5,.05)}${voiceSlider('volume','Гучність','Тихіше','Гучніше',settings.volume,'1.00 — нормальна гучність; фінальне вирівнювання робиться на етапі монтажу.',.5,1.5,.05)}<label>Формат результату<select name="outputFormat"><option value="wav" selected>WAV · без втрати якості · для монтажу</option></select><small>Локальний Piper віддає WAV; MP3 краще створювати як копію для прослуховування, а не для монтажу.</small></label><label class="check"><input name="speakerBoost" type="checkbox" ${settings.speakerBoost?'checked':''}> Підсилення схожості з голосом <small>Збережеться для сумісних зовнішніх TTS; на Piper не впливає.</small></label></fieldset><label>Нотатки для режисера / звукорежисера<textarea name="notes" placeholder="Тембр, темп, обмеження дубляжу…">${esc(voice.notes||'')}</textarea></label><label>Стан<select name="status"><option value="draft" ${voice.status==='draft'?'selected':''}>Чернетка</option><option value="approved" ${voice.status==='approved'?'selected':''}>Затверджено</option><option value="retired" ${voice.status==='retired'?'selected':''}>Не використовувати</option></select></label>`,f=>{const o=Object.fromEntries(f);o.languages=f.getAll('language');o.generationSettings={stability:o.stability,similarityBoost:o.similarityBoost,style:o.style,speed:o.speed,sentenceSilence:o.sentenceSilence,volume:o.volume,outputFormat:o.outputFormat,speakerBoost:f.has('speakerBoost')};delete o.stability;delete o.similarityBoost;delete o.style;delete o.speed;delete o.sentenceSilence;delete o.volume;delete o.outputFormat;delete o.speakerBoost;return api(`/api/projects/${encodeURIComponent(activeId)}/voice-profiles${voiceId?`/${voiceId}`:''}`,{method:voiceId?'PUT':'POST',body:JSON.stringify(o)})})}
function openLocalization(localizationId){const version=localizationId?(active.localizations||[]).find(item=>item.id===localizationId):{language:active.defaultLanguage,status:'planned',videoMasterUri:'',voiceStemUri:'',musicStemUri:'',sfxStemUri:'',subtitlesUri:'',notes:''};modal(localizationId?'Редагувати мовну версію':'Нова мовна версія',`<label>Мова<select name="language"><option value="uk" ${version.language==='uk'?'selected':''}>Українська</option><option value="en" ${version.language==='en'?'selected':''}>Англійська</option></select></label><label>Стан<select name="status"><option value="planned" ${version.status==='planned'?'selected':''}>Заплановано</option><option value="in-progress" ${version.status==='in-progress'?'selected':''}>У роботі</option><option value="approved" ${version.status==='approved'?'selected':''}>Затверджено</option></select></label><label>Video master URI<input name="videoMasterUri" value="${esc(version.videoMasterUri||'')}" placeholder="asset://exports/video-master.mov"></label><label>Voice stem URI<input name="voiceStemUri" value="${esc(version.voiceStemUri||'')}" placeholder="asset://audio/uk/voice.wav"></label><label>Music stem URI<input name="musicStemUri" value="${esc(version.musicStemUri||'')}" placeholder="asset://audio/music.wav"></label><label>SFX stem URI<input name="sfxStemUri" value="${esc(version.sfxStemUri||'')}" placeholder="asset://audio/sfx.wav"></label><label>Субтитри URI<input name="subtitlesUri" value="${esc(version.subtitlesUri||'')}" placeholder="asset://subtitles/uk.vtt"></label><label>Нотатки<textarea name="notes" placeholder="Lipsync-вариант, примітки для YouTube multi-audio…">${esc(version.notes||'')}</textarea></label>`,f=>api(`/api/projects/${encodeURIComponent(activeId)}/localizations${localizationId?`/${localizationId}`:''}`,{method:localizationId?'PUT':'POST',body:JSON.stringify(Object.fromEntries(f))}))}
function queueRender(manifestId){modal('Поставити рендер у чергу',`<p>Завдання буде збережено локально зі статусом «queued». Цей MacBook не виконує Blender-рендер; job чекатиме підключення окремого GPU worker.</p><label>Цільовий формат<select name="target"><option value="preview-720p">Попередній перегляд 720p</option><option value="master-1080p">Майстер 1080p</option><option value="master-4k">Майстер 4K</option></select></label><label>Пріоритет<select name="priority"><option value="normal">Звичайний</option><option value="high">Високий</option></select></label>`,f=>{const o=Object.fromEntries(f);o.manifestId=manifestId;return api(`/api/projects/${encodeURIComponent(activeId)}/render-jobs`,{method:'POST',body:JSON.stringify(o)})})}
function openStage(stageId){const stage=active.workflow.find(item=>item.id===stageId);modal(label('workflow',stageId),`<label>Стан<select name="status"><option value="not-started" ${stage.status==='not-started'?'selected':''}>Не розпочато</option><option value="in-progress" ${stage.status==='in-progress'?'selected':''}>У роботі</option><option value="ready" ${stage.status==='ready'?'selected':''}>Готово до наступного етапу</option><option value="blocked" ${stage.status==='blocked'?'selected':''}>Заблоковано</option></select></label><label>Нотатка для команди<textarea name="note" placeholder="Що зроблено або що блокує роботу">${esc(stage.note||'')}</textarea></label>`,f=>api(`/api/projects/${encodeURIComponent(activeId)}/workflow/${encodeURIComponent(stageId)}`,{method:'POST',body:JSON.stringify(Object.fromEntries(f))}))}
function openProject(){modal('Новий проєкт',`<label>Назва<input name="name" required></label><label>Тип<select name="type"><option value="general">Універсальне відео</option><option value="science">Наукове відео</option><option value="animated-series">Анімаційний серіал</option></select></label><label>Оригінальна мова<select name="defaultLanguage"><option value="uk">Українська</option><option value="en">Англійська</option></select></label><label>Цільова тривалість, хв<input name="targetMinutes" type="number" value="10" min="1"></label><label>Опис<textarea name="description"></textarea></label>`,f=>api('/api/projects',{method:'POST',body:JSON.stringify(Object.fromEntries(f))}))}
function openBible(kind,entryId){const char=kind==='characters',entry=entryId?active.bibles[kind].find(item=>item.id===entryId):{name:'',version:'0.1.0',status:'draft',ageBand:'adult',identityKey:'',role:'',appearance:'',voiceNotes:'',rules:''};modal(entryId?'Редагувати Character Bible':'Новий запис біблії персонажів',`<label>Назва<input name="name" required value="${esc(entry.name)}"></label><label>Версія<input name="version" value="${esc(entry.version)}"></label><label>Статус<select name="status"><option value="draft" ${entry.status==='draft'?'selected':''}>Чернетка</option><option value="approved" ${entry.status==='approved'?'selected':''}>Затверджено</option><option value="superseded" ${entry.status==='superseded'?'selected':''}>Замінено</option></select></label>${char?`<label>Роль у історії<textarea name="role" placeholder="Функція персонажа в епізоді / сезоні">${esc(entry.role||'')}</textarea></label><label>Вікова категорія<select name="ageBand">${['child','teen','young-adult','adult','elder'].map(a=>`<option value="${a}" ${entry.ageBand===a?'selected':''}>${label('age',a)}</option>`).join('')}</select></label><label>Зовнішність і матеріали<textarea name="appearance" placeholder="Силует, кольори, одяг, ключові ознаки">${esc(entry.appearance||'')}</textarea></label><label>Ключ ідентичності голосу/персонажа<input name="identityKey" value="${esc(entry.identityKey||'')}" placeholder="character-v1"></label><label>Голосові нотатки<textarea name="voiceNotes" placeholder="Тембр, темп, вимова, межі дубляжу">${esc(entry.voiceNotes||'')}</textarea></label>`:''}<label>Незмінні правила<textarea name="rules" placeholder="Що має залишатися стабільним між сценами">${esc(entry.rules||'')}</textarea></label>`,f=>api(`/api/projects/${encodeURIComponent(activeId)}/bibles/${kind}${entryId?`/${entryId}`:''}`,{method:entryId?'PUT':'POST',body:JSON.stringify(Object.fromEntries(f))}))}
function openScene(episodeId='',sceneId){const nextOrder=active.scenes.filter(item=>item.episodeId===episodeId).length+1;const scene=sceneId?active.scenes.find(item=>item.id===sceneId):{episodeId,title:'',purpose:'',durationSeconds:10,order:nextOrder,status:'draft',characterIds:[],prompt:''};const chars=active.bibles.characters.filter(c=>c.status==='approved');const episodes=active.episodes||[];modal(sceneId?'Редагувати сцену':'Нова сцена',`<label>Випуск<select name="episodeId"><option value="">— без прив’язки до випуску —</option>${episodes.map(episode=>`<option value="${esc(episode.id)}" ${(episode.id===(scene.episodeId||episodeId))?'selected':''}>Сезон ${episode.seasonNumber} · Випуск ${episode.episodeNumber}: ${esc(episode.title)}</option>`).join('')}</select></label><label>Порядок у випуску<input name="order" type="number" min="1" value="${esc(scene.order||nextOrder)}"></label><label>Назва<input name="title" required value="${esc(scene.title)}"></label><label>Драматична мета<textarea name="purpose">${esc(scene.purpose||'')}</textarea></label><label>Тривалість, секунд<input name="durationSeconds" type="number" value="${esc(scene.durationSeconds)}" min="1"></label><label>Стан<select name="status"><option value="draft" ${(scene.status||'draft')==='draft'?'selected':''}>Чернетка</option><option value="in-review" ${scene.status==='in-review'?'selected':''}>На перевірці</option><option value="approved" ${scene.status==='approved'?'selected':''}>Затверджено</option><option value="production" ${scene.status==='production'?'selected':''}>У виробництві</option></select></label><fieldset><legend>Персонажі сцени</legend>${chars.map(c=>`<label class="check"><input type="checkbox" name="characterId" value="${esc(c.id)}" ${(scene.characterIds||[]).includes(c.id)?'checked':''}> ${esc(c.name)} (${label('age',c.ageBand)})</label>`).join('')||'<p class="empty">Спершу додайте затвердженого персонажа до Character Bible.</p>'}</fieldset><label>Опис для розкадрування<textarea name="prompt" placeholder="Кадр, дія, камера, затверджені референси стилю…">${esc(scene.prompt||'')}</textarea></label>`,f=>{const o=Object.fromEntries(f);o.characterIds=f.getAll('characterId');delete o.characterId;return api(`/api/projects/${encodeURIComponent(activeId)}/scenes${sceneId?`/${sceneId}`:''}`,{method:sceneId?'PUT':'POST',body:JSON.stringify(o)})})}
function openStoryboard(){view='storyboard';render();document.getElementById('storyboard-editor')?.scrollIntoView({behavior:'smooth',block:'center'})}
function selectSceneForDesk(sceneId){const scene=active.scenes.find(item=>item.id===sceneId);activeSceneId=sceneId;activeShotId=scene?.shots?.[0]?.id||null;render()}
async function reorderScript(scriptId,direction){const scripts=[...(active.scripts||[])].filter(item=>!item.deletedAt&&item.visibility!=='hidden').sort((a,b)=>Number(a.order||0)-Number(b.order||0)||String(a.createdAt||'').localeCompare(String(b.createdAt||''))),from=scripts.findIndex(item=>item.id===scriptId),to=from+Number(direction);if(to<0||to>=scripts.length)return;[scripts[from],scripts[to]]=[scripts[to],scripts[from]];try{await api(`/api/projects/${encodeURIComponent(activeId)}/scripts/reorder`,{method:'POST',body:JSON.stringify({scriptIds:scripts.map(item=>item.id)})});await load(activeId)}catch(error){window.alert(error.message)}}
async function setScriptVisibility(scriptId,visibility){try{await api(`/api/projects/${encodeURIComponent(activeId)}/scripts/${encodeURIComponent(scriptId)}/visibility`,{method:'POST',body:JSON.stringify({visibility})});await load(activeId)}catch(error){window.alert(error.message)}}
async function trashScript(scriptId){if(!window.confirm('Перемістити цей сценарій до кошика? Він збережеться там щонайменше 30 днів, тож його можна буде відновити.'))return;try{await api(`/api/projects/${encodeURIComponent(activeId)}/scripts/${encodeURIComponent(scriptId)}`,{method:'DELETE'});await load(activeId)}catch(error){window.alert(error.message)}}
async function restoreScript(scriptId){try{await api(`/api/projects/${encodeURIComponent(activeId)}/scripts/${encodeURIComponent(scriptId)}/restore`,{method:'POST'});await load(activeId)}catch(error){window.alert(error.message)}}
function selectShotForDesk(sceneId,shotId){activeSceneId=sceneId;activeShotId=shotId;render()}
function focusScene(sceneId){activeSceneId=sceneId;activeShotId=active.scenes.find(item=>item.id===sceneId)?.shots?.[0]?.id||null;if(view==='storyboard'){render();document.getElementById('storyboard-editor')?.scrollIntoView({behavior:'smooth',block:'start'});return}view='storyboard';render();document.getElementById('storyboard-editor')?.scrollIntoView({behavior:'smooth',block:'start'})}
function viewSceneShots(sceneId){view='storyboard';render();requestAnimationFrame(()=>focusScene(sceneId))}
function openShot(sceneId,shotId){const scene=active.scenes.find(item=>item.id===sceneId),shot=shotId?scene.shots.find(item=>item.id===shotId):{seconds:'',camera:'medium',imagePrompt:'',motionPrompt:'',lighting:'',action:'',acceptanceCriteria:'',keyImageAssetId:'',referenceAssetIds:[],status:'draft'};const keyImageChoices=active.assets.filter(asset=>['image','reference'].includes(asset.type)&&typeof asset.uri==='string'&&asset.uri.startsWith('/')).map(asset=>`<option value="${esc(asset.id)}" ${shot.keyImageAssetId===asset.id?'selected':''}>${esc(asset.label)} · ${esc(label('status',asset.status))}</option>`).join('');const assetChoices=active.assets.filter(asset=>asset.status==='approved'||asset.type==='reference'||asset.type==='blender-rig'||asset.type==='image').map(asset=>`<label class="check"><input type="checkbox" name="referenceAssetId" value="${esc(asset.id)}" ${(shot.referenceAssetIds||[]).includes(asset.id)?'checked':''}> ${esc(asset.label)} (${esc(label('asset',asset.type))})</label>`).join('')||'<p class="empty">Немає доступних ресурсів. Додайте їх у бібліотеку.</p>';modal(shotId?'Редагувати шот':'Новий шот',`<label>Тривалість, секунд<input name="seconds" type="number" min="1" required value="${esc(shot.seconds)}"></label><label>Камера<input name="camera" value="${esc(shot.camera||'medium')}"></label><label>Обраний ключовий кадр<select name="keyImageAssetId"><option value="">— ще не обрано —</option>${keyImageChoices}</select><small>Для передачі у production потрібне затверджене зображення.</small></label><label>Ключовий кадр / image prompt<textarea name="imagePrompt" placeholder="Композиція, персонажі, дія, середовище…">${esc(shot.imagePrompt||shot.prompt||'')}</textarea></label><label>Рух / video prompt<textarea name="motionPrompt" placeholder="Рух персонажів, камери, темп…">${esc(shot.motionPrompt||'')}</textarea></label><label>Світло<textarea name="lighting" placeholder="Наприклад: м’яке вечірнє світло">${esc(shot.lighting||'')}</textarea></label><label>Що треба змінити або зробити<textarea name="action" placeholder="Наприклад: наблизити Луму, прибрати зайвий ліхтар…">${esc(shot.action||'')}</textarea></label><label>Коли кадр можна вважати готовим<textarea name="acceptanceCriteria" placeholder="Наприклад: видно емоцію Луми, світло веде погляд до ліхтаря…">${esc(shot.acceptanceCriteria||'')}</textarea></label><label>Стан<select name="status"><option value="draft" ${(shot.status||'draft')==='draft'?'selected':''}>Чернетка</option><option value="ready" ${shot.status==='ready'?'selected':''}>Готово до перевірки</option><option value="approved" ${shot.status==='approved'?'selected':''}>Затверджено</option></select></label><fieldset><legend>Прив’язані ресурси</legend>${assetChoices}</fieldset>`,f=>{const o=Object.fromEntries(f);o.referenceAssetIds=f.getAll('referenceAssetId');const endpoint=`/api/projects/${encodeURIComponent(activeId)}/scenes/${sceneId}/shots${shotId?`/${shotId}`:''}`;return api(endpoint,{method:shotId?'PUT':'POST',body:JSON.stringify(o)})})}
function openDialogue(sceneId,lineId){const scene=active.scenes.find(item=>item.id===sceneId),line=lineId?scene.dialogue.find(item=>item.id===lineId):{characterId:'',textUk:'',textEn:'',language:'uk',voiceIdentityKey:'',estimatedSeconds:2,emotion:'',performanceNote:'',status:'draft'},chars=active.bibles.characters.filter(c=>c.status==='approved');modal(lineId?'Редагувати репліку':'Нова репліка',`<label>Персонаж<select name="characterId">${chars.map(c=>`<option value="${esc(c.id)}" ${line.characterId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Українська репліка<textarea name="textUk" placeholder="Залиште порожнім, якщо ще не затверджено">${esc(line.textUk||(line.language==='uk'?(line.text||''):''))}</textarea></label><label>English line<textarea name="textEn" placeholder="Leave blank until approved">${esc(line.textEn||(line.language==='en'?(line.text||''):''))}</textarea></label><label>Основна мова<select name="language"><option value="uk" ${line.language==='uk'?'selected':''}>Українська</option><option value="en" ${line.language==='en'?'selected':''}>Англійська</option></select></label><label>Тривалість репліки, с<input type="number" name="estimatedSeconds" min="1" step="1" required value="${esc(line.estimatedSeconds||2)}"></label><label>Емоція й темп<input name="emotion" value="${esc(line.emotion||'')}" placeholder="Наприклад: тихо, з надією"></label><label>Режисерська примітка<textarea name="performanceNote" placeholder="Пауза, акцент, інтонація, дія в кадрі…">${esc(line.performanceNote||'')}</textarea></label><label>Стан<select name="status"><option value="draft" ${line.status==='draft'?'selected':''}>Чернетка</option><option value="in-review" ${line.status==='in-review'?'selected':''}>На перевірці</option><option value="approved" ${line.status==='approved'?'selected':''}>Затверджено</option></select></label><label>Voice identity key<input name="voiceIdentityKey" required value="${esc(line.voiceIdentityKey||'')}" placeholder="Ідентичність із Character Bible"></label>`,f=>{const o=Object.fromEntries(f),character=chars.find(c=>c.id===o.characterId);o.voiceAgeBand=character.ageBand;const endpoint=`/api/projects/${encodeURIComponent(activeId)}/scenes/${sceneId}/dialogue${lineId?`/${lineId}`:''}`;return api(endpoint,{method:lineId?'PUT':'POST',body:JSON.stringify(o)})})}
function openAsset(assetId){const chars=active.bibles.characters,asset=assetId?active.assets.find(item=>item.id===assetId):{label:'',type:'reference',scope:'other',linkedCharacterId:'',uri:'',version:'0.1.0',notes:'',annotations:[],status:'draft'};if(assetId&&asset?.status==='approved'){modal('Затверджений ресурс',`<p class="ok">Цей ресурс затверджено й він не редагується напряму.</p><div class="item"><strong>${esc(asset.label)}</strong><span class="tag">${esc(label('asset',asset.type)||asset.type)}</span><span class="muted">${esc(asset.uri)} · v${esc(asset.version||'0.1.0')}</span>${asset.notes?`<span class="muted">${esc(asset.notes)}</span>`:''}</div><p class="muted">Створіть нову чернеткову версію в Медіабібліотеці, щоб не перезаписувати затверджений матеріал.</p>`,()=>Promise.resolve());const submit=$('#modal-form button[type="submit"]');if(submit)submit.textContent='Закрити';return;}modal(assetId?'Редагувати ресурс':'Новий ресурс',`<label>Назва<input name="label" required value="${esc(asset.label)}"></label><label>Тип<select name="type">${[['blender-rig','Blender-ріг'],['blender-scene','Blender-сцена'],['reference','Референс'],['image','Зображення'],['video','Відео'],['audio','Аудіо'],['music','Музика'],['ambient','Атмосфера'],['sfx','SFX'],['export','Експорт']].map(([type,name])=>`<option value="${type}" ${asset.type===type?'selected':''}>${name}</option>`).join('')}</select></label><label>Роль у production<select name="scope">${[['character','Персонаж'],['location','Локація'],['object','Об’єкт'],['style','Стиль'],['scene','Сцена'],['shot','Шот'],['audio','Аудіо'],['other','Інше']].map(([scope,name])=>`<option value="${scope}" ${asset.scope===scope?'selected':''}>${name}</option>`).join('')}</select></label><label>Пов’язаний персонаж<select name="linkedCharacterId"><option value="">— не застосовується —</option>${chars.map(character=>`<option value="${esc(character.id)}" ${asset.linkedCharacterId===character.id?'selected':''}>${esc(character.name)}</option>`).join('')}</select></label><label>Шлях / URI<input name="uri" value="${esc(asset.uri)}" placeholder="asset://…" required></label><label>Версія<input name="version" value="${esc(asset.version)}"></label><label>Нотатка для наступного редагування<textarea name="notes" placeholder="Що змінити у цьому референсі, кадрі або аудіо?">${esc(asset.notes||'')}</textarea></label><label>Статус<select name="status"><option value="draft" ${asset.status==='draft'?'selected':''}>Чернетка</option><option value="approved" ${asset.status==='approved'?'selected':''}>Затверджено</option></select></label>`,f=>{const input=Object.fromEntries(f);input.annotations=asset.annotations||[];input.linkedSceneId=asset.linkedSceneId||'';input.linkedShotId=asset.linkedShotId||'';if(asset.audioEdit)input.audioEdit=asset.audioEdit;return api(`/api/projects/${encodeURIComponent(activeId)}/assets${assetId?`/${assetId}`:''}`,{method:assetId?'PUT':'POST',body:JSON.stringify(input)})})}
function fileAsDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Не вдалося прочитати файл.'));reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file)})}
function openImageUpload(){const chars=active.bibles.characters;modal('Завантажити візуальний референс',`<p class="muted">Зображення збережеться локально в бібліотеці цього проєкту. Підтримуються PNG, JPEG і WebP до 10 МБ.</p><label>Файл зображення<input name="file" type="file" accept="image/png,image/jpeg,image/webp" required></label><label>Назва<input name="label" required placeholder="Наприклад: Лума — вираз обличчя, варіант 2"></label><label>Роль у production<select name="scope">${[['character','Персонаж'],['location','Локація'],['object','Об’єкт'],['style','Стиль'],['other','Інше']].map(([scope,name])=>`<option value="${scope}">${name}</option>`).join('')}</select></label><label>Пов’язаний персонаж<select name="linkedCharacterId"><option value="">— не застосовується —</option>${chars.map(character=>`<option value="${esc(character.id)}">${esc(character.name)}</option>`).join('')}</select></label><label>Нотатка<textarea name="notes" placeholder="Що саме в цьому референсі треба зберегти або змінити?"></textarea></label>`,async f=>{const file=f.get('file');if(!(file instanceof File)||!file.size)throw new Error('Оберіть файл зображення.');if(file.size>10*1024*1024)throw new Error('Зображення завелике: максимум 10 МБ.');return api(`/api/projects/${encodeURIComponent(activeId)}/uploads`,{method:'POST',body:JSON.stringify({label:f.get('label'),scope:f.get('scope'),linkedCharacterId:f.get('linkedCharacterId'),notes:f.get('notes'),dataUrl:await fileAsDataUrl(file)})})})}
function createManifest(sceneId){modal('Production manifest',`<p>Manifest буде створено локально, без запуску GPU worker.</p><label>Хто затвердив<input name="approvedBy" required></label>`,f=>{const o=Object.fromEntries(f);o.sceneId=sceneId;return api(`/api/projects/${encodeURIComponent(activeId)}/productions`,{method:'POST',body:JSON.stringify(o)})})}
function downloadManifest(manifestId){window.location.href=`/api/projects/${encodeURIComponent(activeId)}/productions/${encodeURIComponent(manifestId)}/export`}
function downloadEpisodePackage(episodeId){window.location.href=`/api/projects/${encodeURIComponent(activeId)}/episodes/${encodeURIComponent(episodeId)}/export`}
async function downloadDaVinciHandoff(episodeId){try{const validation=await api(`/api/projects/${encodeURIComponent(activeId)}/validate?episodeId=${encodeURIComponent(episodeId)}`,{method:'POST'});if(!validation.valid){window.alert(`DaVinci стане доступним після повного затвердження випуску.\n\nПотрібно виправити:\n• ${validation.errors.map(item=>item.message).join('\n• ')}`);return}window.location.href=`/api/projects/${encodeURIComponent(activeId)}/episodes/${encodeURIComponent(episodeId)}/davinci-handoff`}catch(error){window.alert(error.message||'Не вдалося перевірити готовність випуску.')}}
async function checkProduction(scope={}){const params=new URLSearchParams(scope);const result=await api(`/api/projects/${encodeURIComponent(activeId)}/validate${params.toString()?`?${params}`:''}`,{method:'POST'});const box=document.createElement('div');box.innerHTML=`<div class="card full" style="margin-top:14px"><h3 class="${result.valid?'ok':'error'}">${result.valid?'✓ Перевірку готовності пройдено':'✕ Перевірку готовності не пройдено'}</h3><p class="muted">Перевірено сцен: ${result.scope?.scenesChecked??0}.</p>${result.valid?'<p>Цей фрагмент можна передавати на наступний production-етап. GPU worker усе ще підключається окремо.</p>':result.errors.map(e=>`<div class="item error"><strong>${e.code}</strong>${esc(e.message)}</div>`).join('')}</div>`;$('#content').append(box)}
async function validate(){return checkProduction()}
function selectProject(id){activeId=id;activeEpisodeId=null;load(id).catch(showLoadError)}function showLoadError(error){$('#content').innerHTML=`<div class="card error"><h2>Не вдалося завантажити студію</h2><p>${esc(error.message)}. Перевірте, що локальний сервер запущено, і оновіть сторінку.</p></div>`}
function renderStoryboardShotBrief(){if(view!=='storyboard'||!active)return;const scene=active.scenes.find(item=>item.id===activeSceneId)||active.scenes[0],shot=scene?.shots?.find(item=>item.id===activeShotId)||scene?.shots?.[0],inspector=document.querySelector('.desk-inspector');if(!shot||!inspector)return;const brief=document.createElement('section');brief.className='shot-brief';brief.innerHTML=`<span>РЕЖИСЕРСЬКА ЗАДАЧА</span><p>${esc(shot.action||'Задачу на зміну ще не додано.')}</p><span>КРИТЕРІЙ ГОТОВНОСТІ</span><p>${esc(shot.acceptanceCriteria||'Ще не визначено, за якою ознакою кадр можна прийняти.')}</p><button class="primary" onclick="openShotImageBrief('${esc(scene.id)}','${esc(shot.id)}')">✦ Підготувати запит на зображення</button>`;inspector.append(brief)}
async function copyImageBrief(){try{await navigator.clipboard.writeText(imageBriefText);const button=document.querySelector('.copy-image-brief');if(button){button.textContent='✓ Скопійовано';setTimeout(()=>button.textContent='Копіювати запит',1600)}}catch{window.prompt('Скопіюйте текст вручну:',imageBriefText)}}
async function openShotImageBrief(sceneId,shotId){try{const brief=await api(`/api/projects/${encodeURIComponent(activeId)}/scenes/${encodeURIComponent(sceneId)}/shots/${encodeURIComponent(shotId)}/image-brief`,{method:'POST'});imageBriefText=brief.prompt;modal('Запит на генерацію зображення',`<div class="image-brief-intro"><p class="eyebrow">ЧЕРНЕТКОВИЙ ЗАПИТ · ГЕНЕРАТОР ЩЕ НЕ ПІДКЛЮЧЕНО</p><p>Запит уже зібрав персонажа, стиль, референси та режисерські умови цього шота. Скопіюйте його для генератора або збережіть як основу наступної версії.</p></div><label>Зібраний запит<textarea class="image-brief-text" readonly>${esc(brief.prompt)}</textarea></label><div class="actions"><button class="primary copy-image-brief" type="button" onclick="copyImageBrief()">Копіювати запит</button></div>`,()=>Promise.resolve());document.querySelector('#modal-form button[type="submit"]').textContent='Закрити'}catch(error){window.alert(error.message)}}
async function createLocalVoice(sceneId,lineId,language){const noticeKey=`${sceneId}:${lineId}:${language}`;voiceNotices[noticeKey]={type:'loading',message:'Створюємо чернеткову озвучку…'};render();try{const result=await api(`/api/projects/${encodeURIComponent(activeId)}/scenes/${encodeURIComponent(sceneId)}/dialogue/${encodeURIComponent(lineId)}/synthesize`,{method:'POST',body:JSON.stringify({language})});voiceNotices[noticeKey]={type:'success',message:`Готово: чернеткова озвучка ${result.durationSeconds} с. Прослухайте її нижче.`};await load(activeId)}catch(error){voiceNotices[noticeKey]={type:'error',message:error.message||'Не вдалося створити озвучку.'};render()}}
function openLineVoiceSettings(sceneId,lineId){const scene=active.scenes.find(item=>item.id===sceneId),line=scene?.dialogue.find(item=>item.id===lineId);if(!line)return;const character=active.bibles.characters.find(item=>item.id===line.characterId),profile=(active.voiceProfiles||[]).find(item=>item.identityKey===line.voiceIdentityKey),settings={stability:.5,similarityBoost:.75,style:0,speed:1,sentenceSilence:.2,volume:1,...(profile?.generationSettings||{}),...(line.generationSettings||{})};modal(`Озвучення репліки · ${character?.name||'персонаж'}`,`<div class="voice-settings-intro"><p class="eyebrow">ІНТОНАЦІЯ КОНКРЕТНОЇ РЕПЛІКИ</p><p>Ці значення мають пріоритет над профілем персонажа та вплинуть лише на новий дубль цієї репліки.</p></div><p class="line-voice-quote">${esc(line.textUk||line.text||line.textEn||'Текст репліки ще не задано')}</p><fieldset class="voice-settings">${voiceSlider('speed','Швидкість','Повільніше','Швидше',settings.speed,'Почніть із 0.90–0.95 для важливої або емоційної фрази.',.7,1.2,.05)}${voiceSlider('stability','Стабільність','Більше варіативності','Більш рівно',settings.stability,'Нижче значення дає живішу, але менш передбачувану подачу.',0,1,.05)}${voiceSlider('style','Виразність','Стримано','Виразніше',settings.style,'Змінює варіативність ритму й підкреслює емоційність.',0,1,.05)}${voiceSlider('sentenceSilence','Пауза між реченнями','Без паузи','Довша пауза',settings.sentenceSilence,'Для роздумів або тривоги спробуйте 0.25–0.40 с.',0,1.5,.05)}${voiceSlider('volume','Гучність','Тихіше','Гучніше',settings.volume,'Не використовуйте це замість режисерської вказівки «пошепки» у примітці.',.5,1.5,.05)}</fieldset><label>Режисерська вказівка<textarea name="performanceNote" placeholder="Наприклад: тихо, після короткої паузи; не поспішати з останнім словом.">${esc(line.performanceNote||'')}</textarea></label>`,f=>{const o={...line,generationSettings:{stability:f.get('stability'),similarityBoost:settings.similarityBoost,style:f.get('style'),speed:f.get('speed'),sentenceSilence:f.get('sentenceSilence'),volume:f.get('volume')},performanceNote:f.get('performanceNote')};return api(`/api/projects/${encodeURIComponent(activeId)}/scenes/${encodeURIComponent(sceneId)}/dialogue/${encodeURIComponent(lineId)}`,{method:'PUT',body:JSON.stringify(o)})})}
function renderVoiceSynthesisControls(){if(view!=='audio'||!active)return;const episode=(active.episodes||[]).find(item=>item.id===activeEpisodeId)||(active.episodes||[])[0],scenes=active.scenes.filter(scene=>!episode||scene.episodeId===episode.id).sort((a,b)=>Number(a.order||0)-Number(b.order||0)),items=scenes.flatMap(scene=>(scene.dialogue||[]).map(line=>({scene,line})));document.querySelectorAll('.audio-line').forEach((card,index)=>{const item=items[index];if(!item)return;const language=item.line.language==='en'?'en':'uk',notice=voiceNotices[`${item.scene.id}:${item.line.id}:${language}`],audio=[...(item.line.audioDrafts||[])].reverse().find(draft=>draft.language===language),control=document.createElement('div');control.className='audio-render-control';control.innerHTML=`${notice?`<span class="audio-notice ${esc(notice.type)}" role="status">${esc(notice.message)}</span>`:''}${audio?`<span>Чернеткова озвучка · ${esc(audio.durationSeconds)} с</span><audio controls src="${esc(audio.uri)}"></audio><button onclick="createLocalVoice('${esc(item.scene.id)}','${esc(item.line.id)}','${language}')">Створити заново</button>`:`<span>Звук ще не створено</span><button class="primary" onclick="createLocalVoice('${esc(item.scene.id)}','${esc(item.line.id)}','${language}')" ${notice?.type==='loading'?'disabled':''}>${notice?.type==='loading'?'Створюємо…':'Створити пробний голос'}</button>`}`;card.querySelector('.audio-copy')?.append(control)})}
function renderLineVoiceSettingsButtons(){if(view!=='audio'||!active)return;const episode=(active.episodes||[]).find(item=>item.id===activeEpisodeId)||(active.episodes||[])[0],items=active.scenes.filter(scene=>!episode||scene.episodeId===episode.id).sort((a,b)=>Number(a.order||0)-Number(b.order||0)).flatMap(scene=>(scene.dialogue||[]).map(line=>({scene,line})));document.querySelectorAll('.audio-line').forEach((card,index)=>{const item=items[index],control=card.querySelector('.audio-render-control');if(!item||!control)return;const button=document.createElement('button');button.className='line-voice-settings';button.type='button';button.textContent=item.line.generationSettings?'⚙ Інтонація цієї репліки':'⚙ Налаштувати інтонацію репліки';button.onclick=()=>openLineVoiceSettings(item.scene.id,item.line.id);control.append(button)})}
function renderVoiceSettingsQuickAccess(){if(view!=='audio'||!active)return;const profile=(active.voiceProfiles||[])[0],guide=document.querySelector('.audio-guide');if(!profile||!guide)return;const quick=document.createElement('div');quick.className='voice-settings-quick';quick.innerHTML=`<div><strong>Налаштування голосу</strong><small>${esc(profile.name)} · впливають на нові створені дублі</small></div><button class="primary" onclick="openVoiceProfile('${esc(profile.id)}')">⚙ Відкрити налаштування</button>`;guide.after(quick)}
function scriptEditorPage(){const scriptId=editorState?.scriptId,script=scriptId?(active.scripts||[]).find(item=>item.id===scriptId):{title:'',episodeId:activeEpisodeId||'',logline:'',body:'',status:'draft',...editorState?.initial};if(!script)return '<article class="card full"><p class="error">Сценарій більше не знайдено.</p><button onclick="returnToScriptEditor()">← До сценаріїв</button></article>';const episode=(active.episodes||[]).find(item=>item.id===script.episodeId),scenes=active.scenes.filter(scene=>scene.episodeId===script.episodeId).sort((a,b)=>Number(a.order||0)-Number(b.order||0)),lines=scenes.flatMap(scene=>scene.dialogue||[]),duration=scenes.reduce((sum,scene)=>sum+Number(scene.durationSeconds||0),0),words=(script.body||'').trim().split(/\s+/).filter(Boolean).length;return `<article class="editor-shell"><form id="script-workspace-form" onsubmit="saveScriptEditor(event)"><header class="editor-topbar"><div><button type="button" class="back-link" onclick="returnToScriptEditor()">← Усі сценарії</button><span class="editor-path">Сценарій · ${esc(episode?.title||'без випуску')}</span></div><div class="editor-top-tools"><div class="editor-font-tools" aria-label="Розмір шрифту сценарію"><span>Текст</span><button type="button" title="Зменшити шрифт" onclick="changeScriptFont(-1)">A−</button><output id="script-font-size">${scriptFontSize}</output><button type="button" title="Збільшити шрифт" onclick="changeScriptFont(1)">A+</button></div><span class="tag">${scriptId?'редагування':'нова чернетка'}</span></div></header><section class="editor-main"><label class="editor-title"><span>Назва сценарію</span><input name="title" required value="${esc(script.title)}" placeholder="Робоча назва сценарію"></label><details class="editor-details"><summary><span>Налаштування й логлайн</span><small>${esc(label('status',script.status))} · ${esc(episode?.title||'випуск не обрано')}</small></summary><div class="editor-detail-grid"><label>Випуск<select name="episodeId">${(active.episodes||[]).map(item=>`<option value="${esc(item.id)}" ${script.episodeId===item.id?'selected':''}>Сезон ${item.seasonNumber} · Випуск ${item.episodeNumber}: ${esc(item.title)}</option>`).join('')}</select></label><label>Стан<select name="status"><option value="draft" ${script.status==='draft'?'selected':''}>Чернетка</option><option value="in-review" ${script.status==='in-review'?'selected':''}>На перевірці</option><option value="approved" ${script.status==='approved'?'selected':''}>Затверджено</option></select></label><label class="editor-logline">Логлайн<textarea name="logline" placeholder="Одне-два речення про зміни героя">${esc(script.logline||'')}</textarea></label></div></details><label class="editor-body-label"><span class="editor-writing-label"><strong>Текст сценарію</strong><small>Сцени, дія, репліки та режисерські примітки.</small></span><textarea id="script-workspace-body" name="body" required placeholder="СЦЕНА 1. …\n\nДія: …\n\nЛУМА: …">${esc(script.body||'')}</textarea></label><details class="editor-context"><summary><span>Контекст і режисерська перевірка</span><small>${scenes.length} сцен · ${duration} с · ${lines.length} реплік</small></summary><div class="editor-context-grid"><div class="editor-stat"><b>${scenes.length}</b><span>сцен у плані</span></div><div class="editor-stat"><b>${duration} с</b><span>поточна тривалість</span></div><div class="editor-stat"><b>${lines.length}</b><span>реплік у плані</span></div><div class="editor-check"><strong>✦ Перед збереженням</strong><span>Чи кожна сцена змінює ситуацію?</span><span>Чи репліки звучать природно?</span><span>Чи не з’явився незатверджений канон?</span></div><div class="editor-side-actions"><button type="button" onclick="goToView('storyboard')">▦ Переглянути шоти</button><button type="button" onclick="goToView('audio')">♫ Перевірити репліки</button></div></div></details>${editorNotice?`<p class="editor-success">✓ ${esc(editorNotice)}</p>`:''}${editorError?`<p class="assistant-error">${esc(editorError)}</p>`:''}</section><footer class="editor-actions"><span>${words} слів · попередня версія збережеться автоматично</span><div><button type="button" onclick="returnToScriptEditor()">Скасувати</button><button class="primary" type="submit">💾 Зберегти сценарій</button></div></footer></form></article>`}
function returnToScriptEditor(){editorState=null;editorNotice='';editorError='';view='script';render()}
async function saveScriptEditor(event){event?.preventDefault();const form=document.querySelector('#script-workspace-form');if(!form)return;const payload=Object.fromEntries(new FormData(form));editorError='';try{const saved=await api(`/api/projects/${encodeURIComponent(activeId)}/scripts${editorState?.scriptId?`/${editorState.scriptId}`:''}`,{method:editorState?.scriptId?'PUT':'POST',body:JSON.stringify(payload)});editorState={scriptId:saved.id};editorNotice='Збережено. Попередній стан доступний в «Історії версій».';await load(activeId)}catch(error){editorError=error.message;render()}}
