const workButtonRules=[[/^(?:＋|\+)\s*/, '+', 'Створити'],[/^Створити(?=\s|$)/, '+', 'Створити'],[/^(?:✎\s*)?Редагувати(?=\s|$)/, '✏', 'Редагувати'],[/^⚙\s*(?:Налаштувати|Інтонація|Параметри)/, '⚙', 'Параметри'],[/^(?:💾\s*)?Зберегти(?=\s|$)/, '💾', 'Зберегти'],[/^Скасувати$/, '×', 'Скасувати'],[/^(?:←\s*)?(?:До\s|Усі\sсценарії)/, '←', 'Назад'],[/^(?:◉\s*)?Сховати(?=\s|$)/, '👁', 'Сховати'],[/^(?:◉\s*)?Показати(?=\s|$)/, '👁', 'Показати'],[/^(?:↶\s*)?Відновити(?=\s|$)/, '↶', 'Відновити'],[/^(?:⌫\s*)?(?:До\s+кошика|Видалити)/, '🗑', 'Перемістити до кошика'],[/^⌫$/, '🗑', 'Перемістити до кошика'],[/^(?:▦\s*)?Переглянути(?=\s|$)/, '👁', 'Переглянути'],[/^(?:⛶\s*)?Відкрити(?=\s|$)/, '↗', 'Відкрити'],[/^Завантажити(?=\s|$)/, '↓', 'Завантажити'],[/^Перевірити(?=\s|$)/, '✓', 'Перевірити'],[/^Копіювати(?=\s|$)/, '⧉', 'Копіювати'],[/^(?:♫\s*)?Створити\s+(?:пробний\s+голос|заново)/, '🔊', 'Створити озвучку'],[/^Поставити(?=\s|$)/, '↗', 'Додати до черги'],[/^Manifest$/, '▤', 'Експортувати manifest']];
workButtonRules.unshift([/^Готово$/, '✓', 'Готово'],[/^(?:＋\s*)?Голос$/, '🔊', 'Додати голос'],[/^(?:＋\s*)?Мовна\s+версія$/, '文', 'Додати мовну версію'],[/^Нов(?:ий|а|е)(?=\s|$)/, '+', 'Створити'],[/^Оновити(?=\s|$)/, '↻', 'Оновити'],[/^Очистити(?=\s|$)/, '×', 'Очистити'],[/^Працювати\s+вручну$/, '✏', 'Працювати вручну']);
// Specific actions must precede broad rules such as "Створити".
workButtonRules.unshift([/^(?:♫\s*)?Створити\s+(?:пробний\s+голос|заново)(?=\s|$)/, '♫', 'Створити озвучку'],[/^⚙\s*Відкрити\s+налаштування(?=\s|$)/, '⚙', 'Відкрити налаштування']);
function decorateWorkButtons(root=document){if(!root)return;root.querySelectorAll?.('button:not([data-iconified])').forEach(button=>{const text=button.textContent.replace(/\s+/g,' ').trim(),rule=workButtonRules.find(([pattern])=>pattern.test(text));if(!rule)return;const[,icon,fallback]=rule,label=text||fallback;button.dataset.iconified='true';button.dataset.action=fallback;button.classList.add('icon-button');button.setAttribute('aria-label',label);button.title=label;button.innerHTML=`<span aria-hidden="true">${icon}</span>`});root.querySelectorAll?.('button').forEach(button=>{if(!button.title){const label=button.getAttribute('aria-label')||button.textContent.replace(/\s+/g,' ').trim();if(label)button.title=label}})}
