  const isNew=!existing;
  return `<article class="voice-editor-page"><form id="voice-editor-form" onsubmit="saveVoiceEditor(event)"><header class="voice-editor-top"><div><button class="text-action" type="button" onclick="cancelVoiceEditor()">← До аудіо</button><p class="eyebrow">ПРОФІЛЬ ГОЛОСУ</p><h3>${isNew?'Новий голосовий профіль':esc(voice.name)}</h3><p>Параметри профілю — стартові. Інтонацію конкретної репліки налаштовуйте окремо.</p></div><span class="tag ${provider==='elevenlabs'?'ready':''}">${provider==='elevenlabs'?'ElevenLabs':'Локальний голос'}</span></header><div class="voice-editor-layout"><section class="voice-editor-section"><h4>1. Хто говорить</h4><label>Назва профілю<input name="name" required value="${esc(voice.name)}" placeholder="Наприклад: Лума — українська"></label><label>Ключ ідентичності<input name="identityKey" required value="${esc(voice.identityKey)}" placeholder="luma-uk-v1"></label><label>Вікова категорія<select name="ageBand">${['child','teen','young-adult','adult','elder'].map(age=>`<option value="${age}" ${voice.ageBand===age?'selected':''}>${label('age',age)}</option>`).join('')}</select></label><fieldset class="voice-language"><legend>Мови</legend><label class="check"><input type="checkbox" name="language" value="uk" ${(voice.languages||[]).includes('uk')?'checked':''}> Українська</label><label class="check"><input type="checkbox" name="language" value="en" ${(voice.languages||[]).includes('en')?'checked':''}> Англійська</label></fieldset><label>Нотатка для режисера<textarea name="notes" placeholder="Тембр, вік, характер, мовні особливості…">${esc(voice.notes||'')}</textarea></label></section><section class="voice-editor-section voice-provider-section"><h4>2. Джерело голосу</h4><label>Сервіс<select name="provider" onchange="syncVoiceEditorProvider(this.value)"><option value="elevenlabs" ${provider==='elevenlabs'?'selected':''}>ElevenLabs</option><option value="local" ${provider==='local'?'selected':''}>Локальний тестовий голос</option></select></label><div class="voice-provider-note"><strong>ElevenLabs</strong><span>Доступні голоси завантажуються лише після вашого натискання. Ключ не передається браузеру.</span></div><button type="button" class="eleven-editor-load" onclick="loadElevenLabsVoicesForEditor()">Завантажити доступні голоси</button><label>Голос ElevenLabs<select name="providerVoiceId" class="eleven-editor-voices"><option value="${esc(voice.providerVoiceId||'')}">${voice.providerVoiceId?`Поточний голос · ${esc(voice.providerVoiceId)}`:'Спершу завантажте список голосів'}</option></select></label><label>Модель<select name="modelId"><option value="eleven_multilingual_v2" ${(voice.modelId||'eleven_multilingual_v2')==='eleven_multilingual_v2'?'selected':''}>Eleven Multilingual v2</option></select></label><label>Назва рушія<input name="engine" required value="${esc(voice.engine)}" placeholder="ElevenLabs · Multilingual v2"></label><label>Ліцензія / примітка<input name="license" required value="${esc(voice.license)}" placeholder="Умови використання голосу"></label></section><section class="voice-editor-section voice-delivery-section"><h4>3. Подача голосу</h4><p class="muted">Ці значення задають базу. Для реплік з іншою емоцією використовуйте «Інтонація цієї репліки».</p>${voiceSlider('speed','Швидкість','Повільніше','Швидше',settings.speed,'Для діалогу почніть з 0.90–1.00.',.7,1.2,.05)}${voiceSlider('stability','Стабільність','Більше варіативності','Більш рівно',settings.stability,'Нижче значення — живіше звучання; вище — передбачуваніше.',0,1,.05)}${voiceSlider('similarityBoost','Схожість із голосом','Низька','Висока',settings.similarityBoost,'Зберігає близькість до обраного голосу.',0,1,.05)}${voiceSlider('style','Виразність стилю','Стримано','Виразніше',settings.style,'Для природного діалогу зазвичай достатньо 0.15–0.35.',0,1,.05)}${voiceSlider('sentenceSilence','Пауза між реченнями','Без паузи','Довша пауза',settings.sentenceSilence,'У секундах. Для живого діалогу: 0.15–0.30.',0,1.5,.05)}<details class="voice-advanced"><summary>Додатково: гучність та формат</summary>${voiceSlider('volume','Гучність','Тихіше','Гучніше',settings.volume,'Фінальне вирівнювання робиться під час монтажу.',.5,1.5,.05)}<label>Формат результату<select name="outputFormat"><option value="mp3" ${settings.outputFormat==='mp3'?'selected':''}>MP3 · для пробного прослуховування</option><option value="wav" ${settings.outputFormat==='wav'?'selected':''}>WAV · для монтажу</option></select></label><label class="check"><input name="speakerBoost" type="checkbox" ${settings.speakerBoost?'checked':''}> Підсилення схожості з голосом</label></details></section></div>${voiceEditorError?`<p class="assistant-error">${esc(voiceEditorError)}</p>`:''}${voiceEditorNotice?`<p class="editor-success">${esc(voiceEditorNotice)}</p>`:''}<footer class="voice-editor-actions"><span>Зміни не перезаписують уже створені аудіодублі.</span><div><button type="button" onclick="cancelVoiceEditor()">Скасувати</button><button class="primary" type="submit">Зберегти профіль</button></div></footer></form></article>`
