  if(!models.length){window.alert('У реєстрі ще немає моделі для підготовки зображень.');return}
  const defaultPrompt=`Створити новий варіант кадру «${asset.label}». Використати цей ресурс як референс і зберегти результат лише як чернетку.${asset.notes?` Врахувати правки: ${asset.notes}`:''}`;
