// Audio is a cast, not a single global setting. Show only voices that are
// actually assigned to dialogue in the selected episode, with a clear path to
// edit each profile independently.
renderVoiceSettingsQuickAccess=function(){
  if(view!=='audio'||!active)return;
  document.querySelector('.voice-settings-quick')?.remove();
  const guide=document.querySelector('.audio-guide');
  if(!guide||document.querySelector('.episode-voices'))return;
  const episode=(active.episodes||[]).find(item=>item.id===activeEpisodeId)||(active.episodes||[])[0];
  const characters=active.bibles?.characters||[];
  const voices=active.voiceProfiles||[];
  const lines=active.scenes.filter(scene=>!episode||scene.episodeId===episode.id).flatMap(scene=>scene.dialogue||[]);
  const replyWord=count=>{const last=count%10,lastTwo=count%100;return last===1&&lastTwo!==11?'репліка':last>=2&&last<=4&&(lastTwo<12||lastTwo>14)?'репліки':'реплік'};
  const used=[...new Map(lines.filter(line=>line.voiceIdentityKey).map(line=>[line.voiceIdentityKey,line])).values()].map(line=>{
    const character=characters.find(item=>item.id===line.characterId);
    const voice=voices.find(item=>item.identityKey===line.voiceIdentityKey);
    const takes=lines.filter(item=>item.voiceIdentityKey===line.voiceIdentityKey).length;
    return {character,voice,takes};
  });
  const cards=used.map(({character,voice,takes})=>{
    const characterName=character?.name||'Персонаж';
    if(!voice)return `<article class="episode-voice-card is-missing"><div><strong>${esc(characterName)}</strong><small>${takes} ${replyWord(takes)} · голос ще не додано</small></div><button type="button" onclick="openVoiceProfile()" aria-label="Додати голос для ${esc(characterName)}" title="Додати голос для ${esc(characterName)}">＋</button></article>`;
    const provider=voice.provider==='elevenlabs'?'ElevenLabs':'локальний тестовий голос';
    return `<article class="episode-voice-card"><div class="episode-voice-copy"><strong>${esc(characterName)}</strong><span>${esc(voice.name)}</span><small>${takes} ${replyWord(takes)} · ${esc(provider)} · ${esc(label('status',voice.status||'draft'))}</small></div><button type="button" onclick="openVoiceProfile('${esc(voice.id)}')" aria-label="Налаштувати голос ${esc(characterName)}" title="Налаштувати голос ${esc(characterName)}">⚙</button></article>`;
  }).join('');
  const empty='<p class="muted">У репліках цього випуску ще не призначено голосів.</p>';
  const panel=document.createElement('section');
  panel.className='episode-voices';
  panel.innerHTML=`<div class="episode-voices-head"><div><p class="eyebrow">ГОЛОСИ ВИПУСКУ</p><h4>Окремий профіль для кожного персонажа</h4><p>Базове звучання налаштовується тут, а інтонація — у картці конкретної репліки.</p></div><button type="button" onclick="openVoiceProfile()" aria-label="Додати голосовий профіль" title="Додати голосовий профіль">＋</button></div><div class="episode-voices-list">${cards||empty}</div>`;
  guide.after(panel);
}

// Every substantial editor uses one consistent, full-screen workspace. The
// two short operational confirmations remain compact; the image annotator and
// focus mode already own specialised full-screen layouts.
const compactDialogTitles=new Set(['Поставити рендер у чергу','Production manifest']);
const studioWorkspaceModal=modal;
modal=function(title,fields,handler){
  const modalEl=$('#modal');
  const isWorkspace=!compactDialogTitles.has(title);
  modalEl.classList.remove('reference-dialog','focus-dialog');
  modalEl.classList.toggle('workspace-dialog',isWorkspace);
  modalEl.dataset.workspaceForm=isWorkspace?'true':'false';
  studioWorkspaceModal(title,fields,handler);
  if(isWorkspace){
    $('#modal-form')?.classList.add('workspace-form');
    $('#modal-fields')?.setAttribute('aria-label',`Редагування: ${title}`);
  }
}
